-- CorteCerto: migrations 0003 to 0024 in one go, for a project that has run 0001 and 0002.
-- Generated by scripts/bundle-migrations.sh from supabase/migrations/. Do not edit by hand.
-- Paste all of it in Supabase > SQL Editor and press Run. If anything fails, nothing is applied.
begin;

-- ======================================================================
-- 0003_client_notes.sql
-- ======================================================================
-- Notes and birthdays the salon keeps about each client.
-- Clients are identified by their phone digits (e.g. 351912345678), the same key
-- the client list uses to group bookings. Only the salon owner can read or write.
-- The birthday keeps only day and month: the year is not needed and is not asked.

create table client_notes (
  salon_id uuid not null references salons(id) on delete cascade,
  phone_key text not null check (phone_key ~ '^[0-9]{6,15}$'),
  notes text not null default '' check (length(notes) <= 2000),
  birthday_day smallint check (birthday_day between 1 and 31),
  birthday_month smallint check (birthday_month between 1 and 12),
  updated_at timestamptz not null default now(),
  primary key (salon_id, phone_key),
  check ((birthday_day is null) = (birthday_month is null))
);

alter table client_notes enable row level security;

create policy client_notes_owner on client_notes for all
  using (is_owner(salon_id)) with check (is_owner(salon_id));

-- ======================================================================
-- 0004_legal_acceptances.sql
-- ======================================================================
-- Record of each salon owner accepting the terms and the data processing agreement.
-- One row per acceptance, never updated or deleted by the app, so the history
-- shows which version was accepted, when, and from which browser.
-- When a document gets a new version, the app asks the owner to accept again.

create type legal_document as enum ('termos', 'tratamento_dados');

create table legal_acceptances (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  salon_id uuid references salons(id) on delete cascade, -- null when accepted before the salon exists
  document legal_document not null,
  version text not null check (version ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'),
  accepted_at timestamptz not null default now(),
  user_agent text check (length(user_agent) <= 400)
);
create index legal_acceptances_user on legal_acceptances (user_id, document, version);

alter table legal_acceptances enable row level security;

-- The owner reads and adds their own acceptances. No update or delete policy:
-- the record can't be changed from the app.
create policy legal_read_own on legal_acceptances for select using (user_id = auth.uid());
create policy legal_insert_own on legal_acceptances for insert with check (
  user_id = auth.uid() and (salon_id is null or is_owner(salon_id))
);

-- The server sets who and when, so neither can be forged from the browser.
create function legal_acceptance_stamp() returns trigger
language plpgsql set search_path = public as $$
begin
  new.user_id := auth.uid();
  new.accepted_at := now();
  return new;
end;
$$;

create trigger legal_acceptance_stamp before insert on legal_acceptances
  for each row execute function legal_acceptance_stamp();

-- ======================================================================
-- 0005_booking_emails.sql
-- ======================================================================
-- Email to the salon owner for each new booking, sent by the Cloudflare Worker.
-- The Worker calls claim_booking_notification with the service role key (a secret
-- kept in Cloudflare). Each booking can be claimed once, and only in its first
-- 10 minutes, so the endpoint can't be used to send repeated or old emails.

alter table bookings add column owner_notified_at timestamptz;

create function claim_booking_notification(p_booking uuid)
returns table (
  owner_email text, salon_name text, salon_timezone text,
  client_name text, client_phone text, consent_messages boolean,
  service_name text, price_cents int, professional_name text,
  starts_at timestamptz, deposit deposit_status
)
language sql security definer set search_path = public as $$
  with claimed as (
    update bookings b set owner_notified_at = now()
    where b.id = p_booking and b.owner_notified_at is null
      and b.created_at > now() - interval '10 minutes'
    returning b.*
  )
  select u.email::text, s.name, s.timezone,
         c.client_name, c.client_phone, c.consent_messages,
         sv.name, sv.price_cents, p.name, c.starts_at, c.deposit
  from claimed c
  join salons s on s.id = c.salon_id
  join auth.users u on u.id = s.owner_id
  join services sv on sv.id = c.service_id
  join professionals p on p.id = c.professional_id;
$$;

-- Only the Worker (service role) may call it: it returns the owner's email.
revoke execute on function claim_booking_notification(uuid) from public, anon, authenticated;
grant execute on function claim_booking_notification(uuid) to service_role;

-- ======================================================================
-- 0006_reminders.sql
-- ======================================================================
-- When the salon sent the WhatsApp reminder for a booking, so it isn't sent twice.
-- The owner already updates bookings under the bookings_owner policy.
alter table bookings add column reminder_sent_at timestamptz;

-- ======================================================================
-- 0007_client_changes.sql
-- ======================================================================
-- Clients cancel or move their own booking from a private link: /m/<booking id>.
-- The booking id is a random UUID that only the client (on the confirmation page
-- and in the salon's WhatsApp messages) and the salon know.

-- Hours before the start until which clients may cancel or move. Null: not allowed.
alter table salons add column client_change_hours smallint default 2
  check (client_change_hours is null or client_change_hours between 0 and 168);

-- What the client last did, shown on the salon's agenda.
alter table bookings add column client_action text check (client_action in ('cancelou', 'mudou'));
alter table bookings add column client_action_at timestamptz;

-- The booking as the client sees it. No other clients' data, no salon-only fields.
create function booking_for_client(p_booking uuid)
returns table (
  id uuid, status booking_status, deposit deposit_status, starts_at timestamptz, ends_at timestamptz,
  client_name text, salon_id uuid, salon_slug text, salon_name text, salon_theme text,
  salon_timezone text, salon_whatsapp text, mbway_number text, deposit_cents int,
  client_change_hours smallint, service_id uuid, service_name text, duration_min int,
  price_cents int, professional_id uuid, professional_name text
)
language sql stable security definer set search_path = public as $$
  select b.id, b.status, b.deposit, b.starts_at, b.ends_at, b.client_name,
         s.id, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.mbway_number, s.deposit_cents,
         s.client_change_hours, sv.id, sv.name, sv.duration_min, sv.price_cents, p.id, p.name
  from bookings b
  join salons s on s.id = b.salon_id
  join services sv on sv.id = b.service_id
  join professionals p on p.id = b.professional_id
  where b.id = p_booking;
$$;

-- Raises unless the client may still change this booking. Returns its row, locked.
create function client_change_check(p_booking uuid) returns bookings
language plpgsql security definer set search_path = public as $$
declare
  b bookings;
  v_hours smallint;
begin
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'marcacao_inexistente'; end if;
  if b.status not in ('pendente', 'confirmada') then raise exception 'marcacao_fechada'; end if;
  select client_change_hours into v_hours from salons where id = b.salon_id;
  if v_hours is null then raise exception 'alteracao_nao_permitida'; end if;
  if b.starts_at - make_interval(hours => v_hours) < now() then raise exception 'fora_do_prazo'; end if;
  return b;
end;
$$;

create function cancel_booking_by_client(p_booking uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform client_change_check(p_booking);
  update bookings set status = 'cancelada', client_action = 'cancelou', client_action_at = now()
  where id = p_booking;
end;
$$;

create function move_booking_by_client(p_booking uuid, p_starts_at timestamptz) returns void
language plpgsql security definer set search_path = public as $$
declare
  b bookings;
  v_duration int;
begin
  b := client_change_check(p_booking);
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  select duration_min into v_duration from services where id = b.service_id;
  -- Back to pending, so the salon sees and confirms the new time.
  update bookings set starts_at = p_starts_at, ends_at = p_starts_at + make_interval(mins => v_duration),
         status = 'pendente', client_action = 'mudou', client_action_at = now(), reminder_sent_at = null
  where id = p_booking;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

revoke execute on function client_change_check(uuid) from public, anon, authenticated;
grant execute on function booking_for_client(uuid) to anon, authenticated;
grant execute on function cancel_booking_by_client(uuid) to anon, authenticated;
grant execute on function move_booking_by_client(uuid, timestamptz) to anon, authenticated;

-- ======================================================================
-- 0008_walkin_queue.sql
-- ======================================================================
-- Walk-in queue: clients scan the salon's QR code, join the queue with their name
-- and phone, and see how many people are ahead. The salon calls them by WhatsApp.

alter table salons add column queue_open boolean not null default false;

create type walkin_status as enum ('espera', 'chamado', 'atendido', 'saiu');

create table walkins (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  client_name text not null check (length(trim(client_name)) between 1 and 80),
  client_phone text check (client_phone is null or length(client_phone) between 9 and 20),
  consent_messages boolean not null default false,
  status walkin_status not null default 'espera',
  created_at timestamptz not null default now(),
  called_at timestamptz,
  finished_at timestamptz
);
create index walkins_salon_open on walkins (salon_id, created_at) where status in ('espera', 'chamado');
-- One place in the queue per phone at a time.
create unique index walkins_one_per_phone on walkins (salon_id, client_phone)
  where status in ('espera', 'chamado') and client_phone is not null;

alter table walkins enable row level security;
create policy walkins_owner on walkins for all using (is_owner(salon_id)) with check (is_owner(salon_id));

-- Clients join without an account. Returns the place id, kept in their browser.
create function join_queue(p_salon uuid, p_name text, p_phone text, p_consent boolean)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  perform 1 from salons where id = p_salon and queue_open;
  if not found then raise exception 'fila_fechada'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 or length(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g')) < 9 then
    raise exception 'dados_cliente';
  end if;
  -- Already in the queue with this phone: hand back the same place.
  select id into v_id from walkins
    where salon_id = p_salon and client_phone = trim(p_phone) and status in ('espera', 'chamado');
  if found then return v_id; end if;
  insert into walkins (salon_id, client_name, client_phone, consent_messages)
  values (p_salon, trim(p_name), trim(p_phone), coalesce(p_consent, false))
  returning id into v_id;
  return v_id;
end;
$$;

-- What the client sees: their status, how many are ahead, and what the estimate needs.
create function queue_status(p_walkin uuid)
returns table (
  status walkin_status, ahead int, client_name text,
  salon_name text, salon_slug text, salon_theme text, queue_open boolean,
  avg_minutes int, professionals int
)
language sql stable security definer set search_path = public as $$
  select w.status,
         (select count(*)::int from walkins o where o.salon_id = w.salon_id and o.status = 'espera' and o.created_at < w.created_at),
         w.client_name, s.name, s.slug, s.theme, s.queue_open,
         coalesce((select round(avg(duration_min))::int from services where salon_id = s.id and active), 30),
         greatest((select count(*)::int from professionals where salon_id = s.id and active), 1)
  from walkins w join salons s on s.id = w.salon_id
  where w.id = p_walkin;
$$;

-- How long the queue is right now, for the join page.
create function queue_length(p_salon uuid) returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from walkins where salon_id = p_salon and status = 'espera';
$$;

create function leave_queue(p_walkin uuid) returns void
language sql security definer set search_path = public as $$
  update walkins set status = 'saiu', finished_at = now() where id = p_walkin and status in ('espera', 'chamado');
$$;

grant execute on function join_queue(uuid, text, text, boolean) to anon, authenticated;
grant execute on function queue_status(uuid) to anon, authenticated;
grant execute on function queue_length(uuid) to anon, authenticated;
grant execute on function leave_queue(uuid) to anon, authenticated;

-- ======================================================================
-- 0009_schedules.sql
-- ======================================================================
-- Each professional's own weekly hours, and time off (holidays, days off, blocked hours).
-- Run after 0007 (this replaces move_booking_by_client).

-- A professional with rows here works these hours; one without rows follows the
-- salon's opening hours. Several rows on one weekday make a break (e.g. lunch).
create table professional_hours (
  professional_id uuid not null references professionals(id) on delete cascade,
  salon_id uuid not null references salons(id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),
  opens time not null,
  closes time not null check (closes > opens),
  primary key (professional_id, weekday, opens)
);

-- Time nobody can book. professional_id null: the whole salon (e.g. a holiday).
create table time_off (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  professional_id uuid references professionals(id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  reason text check (length(reason) <= 80),
  created_at timestamptz not null default now()
);
create index time_off_salon on time_off (salon_id, starts_at);

alter table professional_hours enable row level security;
alter table time_off enable row level security;

-- Hours are public, like the salon's opening hours, so the booking page can show free times.
create policy pro_hours_public_read on professional_hours for select using (true);
create policy pro_hours_owner_write on professional_hours for all
  using (is_owner(salon_id)) with check (is_owner(salon_id));
-- Time off is private (the reason is the salon's business); clients only see it as busy time.
create policy time_off_owner on time_off for all using (is_owner(salon_id)) with check (is_owner(salon_id));

-- Busy time now includes time off, without its reason. Salon-wide time off is
-- returned once per professional.
create or replace function busy_slots(p_salon uuid, p_from timestamptz, p_to timestamptz)
returns table (professional_id uuid, starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = public as $$
  select b.professional_id, b.starts_at, b.ends_at
  from bookings b
  where b.salon_id = p_salon
    and b.status in ('pendente', 'confirmada', 'concluida')
    and b.starts_at < p_to and b.ends_at > p_from
  union all
  select p.id, t.starts_at, t.ends_at
  from time_off t
  join professionals p on p.salon_id = t.salon_id and (t.professional_id is null or t.professional_id = p.id)
  where t.salon_id = p_salon and t.starts_at < p_to and t.ends_at > p_from;
$$;

-- True when the professional has time off overlapping the interval.
create function is_time_off(p_professional uuid, p_from timestamptz, p_to timestamptz) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from time_off t join professionals p on p.id = p_professional
    where t.salon_id = p.salon_id and (t.professional_id is null or t.professional_id = p_professional)
      and t.starts_at < p_to and t.ends_at > p_from
  );
$$;
revoke execute on function is_time_off(uuid, timestamptz, timestamptz) from public, anon, authenticated;

-- Client bookings and moves can't land on time off.
create or replace function create_booking(
  p_salon uuid, p_service uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_deposit int;
  v_id uuid;
begin
  select duration_min into v_duration from services
    where id = p_service and salon_id = p_salon and active;
  if v_duration is null then raise exception 'servico_invalido'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon and active;
  if not found then raise exception 'profissional_invalido'; end if;
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  if length(trim(p_client_name)) = 0 or length(trim(p_client_phone)) < 9 then
    raise exception 'dados_cliente';
  end if;
  if is_time_off(p_professional, p_starts_at, p_starts_at + make_interval(mins => v_duration)) then
    raise exception 'horario_ocupado';
  end if;
  select deposit_cents into v_deposit from salons where id = p_salon;

  insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at,
                        client_name, client_phone, consent_messages, deposit)
  values (p_salon, p_service, p_professional, p_starts_at,
          p_starts_at + make_interval(mins => v_duration),
          trim(p_client_name), trim(p_client_phone), coalesce(p_consent, false),
          case when v_deposit > 0 then 'pendente'::deposit_status else 'nenhum' end)
  returning id into v_id;
  return v_id;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

create or replace function move_booking_by_client(p_booking uuid, p_starts_at timestamptz) returns void
language plpgsql security definer set search_path = public as $$
declare
  b bookings;
  v_duration int;
begin
  b := client_change_check(p_booking);
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  select duration_min into v_duration from services where id = b.service_id;
  if is_time_off(b.professional_id, p_starts_at, p_starts_at + make_interval(mins => v_duration)) then
    raise exception 'horario_ocupado';
  end if;
  update bookings set starts_at = p_starts_at, ends_at = p_starts_at + make_interval(mins => v_duration),
         status = 'pendente', client_action = 'mudou', client_action_at = now(), reminder_sent_at = null
  where id = p_booking;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

-- ======================================================================
-- 0010_privacy.sql
-- ======================================================================
-- RGPD: forget a client on request, and forget clients inactive for 3 years.
-- Forgetting keeps the bookings for the salon's statistics but removes who they
-- were: name and phone are replaced, consent is cleared, notes are deleted.
-- Run after 0003 (client_notes) and 0008 (walkins).

-- The same phone key the app uses: digits only, 00 prefix dropped, 351 added to 9-digit numbers.
create function phone_key(p text) returns text
language sql immutable as $$
  select case
    when length(d) = 9 then '351' || d
    else d
  end
  from (select regexp_replace(regexp_replace(coalesce(p, ''), '\D', '', 'g'), '^00', '') as d) x;
$$;

create function forget_client_rows(p_salon uuid, p_key text) returns int
language plpgsql security definer set search_path = public as $$
declare v_count int;
begin
  -- Future bookings still on are cancelled: nobody to remind or call any more.
  update bookings set status = 'cancelada'
  where salon_id = p_salon and phone_key(client_phone) = p_key
    and status in ('pendente', 'confirmada') and starts_at > now();
  update bookings set client_name = 'Cliente apagado', client_phone = '', consent_messages = false
  where salon_id = p_salon and phone_key(client_phone) = p_key;
  get diagnostics v_count = row_count;
  delete from client_notes where salon_id = p_salon and phone_key = p_key;
  delete from walkins where salon_id = p_salon and phone_key(client_phone) = p_key;
  return v_count;
end;
$$;
revoke execute on function forget_client_rows(uuid, text) from public, anon, authenticated;

-- Called by the salon owner from the client list.
create function forget_client(p_salon uuid, p_key text) returns int
language plpgsql security definer set search_path = public as $$
begin
  if not is_owner(p_salon) then raise exception 'sem_permissao'; end if;
  if p_key !~ '^[0-9]{6,15}$' then raise exception 'telefone_invalido'; end if;
  return forget_client_rows(p_salon, p_key);
end;
$$;
grant execute on function forget_client(uuid, text) to authenticated;

-- Clients whose last booking was more than 3 years ago, in every salon.
create function forget_inactive_clients() returns int
language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_total int := 0;
begin
  for r in
    select salon_id, phone_key(client_phone) as k
    from bookings
    where client_phone <> ''
    group by salon_id, phone_key(client_phone)
    having max(starts_at) < now() - interval '3 years'
  loop
    v_total := v_total + forget_client_rows(r.salon_id, r.k);
  end loop;
  return v_total;
end;
$$;
revoke execute on function forget_inactive_clients() from public, anon, authenticated;

-- Run it every night at 03:30 if pg_cron is available (Supabase: Database > Extensions > pg_cron).
-- Without pg_cron the migration still succeeds; enable the extension and run this block again.
do $$
begin
  create extension if not exists pg_cron;
  perform cron.schedule('forget-inactive-clients', '30 3 * * *', 'select public.forget_inactive_clients()');
exception when others then
  raise notice 'pg_cron not available: inactive clients will not be forgotten automatically (%).', sqlerrm;
end;
$$;

-- ======================================================================
-- 0011_professional_prices.sql
-- ======================================================================
-- Prices and durations per professional, and the price kept on each booking.
-- Run after 0009 (this replaces create_booking and move_booking_by_client).

-- Optional: a professional charges a different price, takes a different time,
-- or doesn't do a service at all. Without a row, the service's own values apply.
create table service_overrides (
  service_id uuid not null references services(id) on delete cascade,
  professional_id uuid not null references professionals(id) on delete cascade,
  salon_id uuid not null references salons(id) on delete cascade,
  offered boolean not null default true,
  price_cents int check (price_cents is null or price_cents between 0 and 100000),
  duration_min int check (duration_min is null or duration_min between 5 and 600),
  primary key (service_id, professional_id)
);
alter table service_overrides enable row level security;
create policy overrides_public_read on service_overrides for select using (true);
create policy overrides_owner_write on service_overrides for all
  using (is_owner(salon_id)) with check (is_owner(salon_id));

-- The price at the time of booking, so revenue doesn't change when prices do.
alter table bookings add column price_cents int;
update bookings b set price_cents = s.price_cents from services s where s.id = b.service_id and b.price_cents is null;

-- Price and duration for a service with a given professional; null when they don't do it.
create function effective_service(p_service uuid, p_professional uuid)
returns table (price_cents int, duration_min int)
language sql stable security definer set search_path = public as $$
  select coalesce(o.price_cents, s.price_cents), coalesce(o.duration_min, s.duration_min)
  from services s
  left join service_overrides o on o.service_id = s.id and o.professional_id = p_professional
  where s.id = p_service and s.active and coalesce(o.offered, true);
$$;

create or replace function create_booking(
  p_salon uuid, p_service uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price int;
  v_deposit int;
  v_id uuid;
begin
  perform 1 from services where id = p_service and salon_id = p_salon and active;
  if not found then raise exception 'servico_invalido'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon and active;
  if not found then raise exception 'profissional_invalido'; end if;
  select e.price_cents, e.duration_min into v_price, v_duration from effective_service(p_service, p_professional) e;
  if v_duration is null then raise exception 'servico_invalido'; end if;
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  if length(trim(p_client_name)) = 0 or length(trim(p_client_phone)) < 9 then
    raise exception 'dados_cliente';
  end if;
  if is_time_off(p_professional, p_starts_at, p_starts_at + make_interval(mins => v_duration)) then
    raise exception 'horario_ocupado';
  end if;
  select deposit_cents into v_deposit from salons where id = p_salon;

  insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at,
                        client_name, client_phone, consent_messages, deposit, price_cents)
  values (p_salon, p_service, p_professional, p_starts_at,
          p_starts_at + make_interval(mins => v_duration),
          trim(p_client_name), trim(p_client_phone), coalesce(p_consent, false),
          case when v_deposit > 0 then 'pendente'::deposit_status else 'nenhum' end, v_price)
  returning id into v_id;
  return v_id;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

-- A moved booking keeps its own length.
create or replace function move_booking_by_client(p_booking uuid, p_starts_at timestamptz) returns void
language plpgsql security definer set search_path = public as $$
declare
  b bookings;
  v_length interval;
begin
  b := client_change_check(p_booking);
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  v_length := b.ends_at - b.starts_at;
  if is_time_off(b.professional_id, p_starts_at, p_starts_at + v_length) then
    raise exception 'horario_ocupado';
  end if;
  update bookings set starts_at = p_starts_at, ends_at = p_starts_at + v_length,
         status = 'pendente', client_action = 'mudou', client_action_at = now(), reminder_sent_at = null
  where id = p_booking;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

-- The client's page shows the booking's own price and length.
create or replace function booking_for_client(p_booking uuid)
returns table (
  id uuid, status booking_status, deposit deposit_status, starts_at timestamptz, ends_at timestamptz,
  client_name text, salon_id uuid, salon_slug text, salon_name text, salon_theme text,
  salon_timezone text, salon_whatsapp text, mbway_number text, deposit_cents int,
  client_change_hours smallint, service_id uuid, service_name text, duration_min int,
  price_cents int, professional_id uuid, professional_name text
)
language sql stable security definer set search_path = public as $$
  select b.id, b.status, b.deposit, b.starts_at, b.ends_at, b.client_name,
         s.id, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.mbway_number, s.deposit_cents,
         s.client_change_hours, sv.id, sv.name,
         (extract(epoch from (b.ends_at - b.starts_at)) / 60)::int,
         coalesce(b.price_cents, sv.price_cents), p.id, p.name
  from bookings b
  join salons s on s.id = b.salon_id
  join services sv on sv.id = b.service_id
  join professionals p on p.id = b.professional_id
  where b.id = p_booking;
$$;

-- ======================================================================
-- 0012_client_errors.sql
-- ======================================================================
-- Errors from the app in people's browsers, sent through the Worker (service role).
-- No policies: nobody can read or write this table from the app itself.
-- Holds no client data: message, stack, page path without query, browser, release.

create table client_errors (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  message text not null check (length(message) <= 500),
  stack text check (length(stack) <= 4000),
  path text check (length(path) <= 200),
  user_agent text check (length(user_agent) <= 300),
  release text check (length(release) <= 40)
);
create index client_errors_at on client_errors (at desc);
alter table client_errors enable row level security;

-- Keep 30 days, if pg_cron is available.
do $$
begin
  create extension if not exists pg_cron;
  perform cron.schedule('trim-client-errors', '45 3 * * *', $c$delete from public.client_errors where at < now() - interval '30 days'$c$);
exception when others then
  raise notice 'pg_cron not available: old client errors will not be trimmed automatically (%).', sqlerrm;
end;
$$;

-- ======================================================================
-- 0013_team_accounts.sql
-- ======================================================================
-- Team accounts: the owner invites people by email; once they sign in with that
-- email they join the salon. Team members use the agenda, week, clients, queue
-- and reminders. Settings, prices, hours, statistics, exports and deleting
-- client data stay with the owner.
-- Run after 0003, 0008 and 0009 (it adds team access to their tables).

create table salon_members (
  salon_id uuid not null references salons(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  email text not null,
  professional_id uuid references professionals(id) on delete set null, -- whose agenda is theirs
  created_at timestamptz not null default now(),
  primary key (salon_id, user_id)
);
-- One salon per person, so the app knows which one to open.
create unique index salon_members_one_salon on salon_members (user_id);

create table salon_invites (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  email text not null check (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  professional_id uuid references professionals(id) on delete set null,
  created_at timestamptz not null default now(),
  accepted_at timestamptz
);
create unique index salon_invites_open on salon_invites (salon_id, lower(email)) where accepted_at is null;

alter table salon_members enable row level security;
alter table salon_invites enable row level security;

create policy members_owner on salon_members for all using (is_owner(salon_id)) with check (is_owner(salon_id));
create policy members_self_read on salon_members for select using (user_id = auth.uid());
create policy invites_owner on salon_invites for all using (is_owner(salon_id)) with check (is_owner(salon_id));

create function is_member(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from salon_members where salon_id = s and user_id = auth.uid());
$$;

-- Team access, added next to the owner's policies (policies of the same command are combined with OR).
-- No delete: removing data stays with the owner.
create policy bookings_team_read on bookings for select using (is_member(salon_id));
create policy bookings_team_insert on bookings for insert with check (is_member(salon_id));
create policy bookings_team_update on bookings for update using (is_member(salon_id)) with check (is_member(salon_id));
create policy notes_team_read on client_notes for select using (is_member(salon_id));
create policy notes_team_insert on client_notes for insert with check (is_member(salon_id));
create policy notes_team_update on client_notes for update using (is_member(salon_id)) with check (is_member(salon_id));
create policy walkins_team_read on walkins for select using (is_member(salon_id));
create policy walkins_team_insert on walkins for insert with check (is_member(salon_id));
create policy walkins_team_update on walkins for update using (is_member(salon_id)) with check (is_member(salon_id));
create policy time_off_team_read on time_off for select using (is_member(salon_id));
-- Opening and closing the queue is a team task too: only that column, through a function.
create function set_queue_open(p_salon uuid, p_open boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not (is_owner(p_salon) or is_member(p_salon)) then raise exception 'sem_permissao'; end if;
  update salons set queue_open = p_open where id = p_salon;
end;
$$;
grant execute on function set_queue_open(uuid, boolean) to authenticated;

-- Joins the salons that invited the signed-in email (invites last 14 days).
create function accept_invites() returns int
language plpgsql security definer set search_path = public as $$
declare
  v_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  r record;
  v_count int := 0;
begin
  if auth.uid() is null or v_email = '' then return 0; end if;
  if exists (select 1 from salons where owner_id = auth.uid()) or exists (select 1 from salon_members where user_id = auth.uid()) then
    return 0;
  end if;
  for r in select * from salon_invites
           where lower(email) = v_email and accepted_at is null and created_at > now() - interval '14 days'
           order by created_at desc limit 1
  loop
    insert into salon_members (salon_id, user_id, email, professional_id)
    values (r.salon_id, auth.uid(), v_email, r.professional_id) on conflict do nothing;
    update salon_invites set accepted_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
grant execute on function accept_invites() to authenticated;

-- The salon the signed-in person works in, and how.
create function my_salon() returns table (salon_id uuid, role text, professional_id uuid)
language sql stable security definer set search_path = public as $$
  select id, 'dono', null::uuid from salons where owner_id = auth.uid()
  union all
  select m.salon_id, 'equipa', m.professional_id from salon_members m where m.user_id = auth.uid()
  limit 1;
$$;
grant execute on function my_salon() to authenticated;

-- ======================================================================
-- 0014_change_emails.sql
-- ======================================================================
-- Email to the salon owner when a client cancels or moves a booking (sent by the Worker).
-- Like 0005: only the service role can claim, once per client action, within 10 minutes.
-- Run after 0007.

alter table bookings add column client_change_notified_at timestamptz;

create function claim_client_change_notification(p_booking uuid)
returns table (
  owner_email text, salon_name text, salon_timezone text, action text,
  client_name text, client_phone text, service_name text, professional_name text, starts_at timestamptz
)
language sql security definer set search_path = public as $$
  with claimed as (
    update bookings b set client_change_notified_at = now()
    where b.id = p_booking and b.client_action is not null
      and b.client_action_at > now() - interval '10 minutes'
      and (b.client_change_notified_at is null or b.client_change_notified_at < b.client_action_at)
    returning b.*
  )
  select u.email::text, s.name, s.timezone, c.client_action,
         c.client_name, c.client_phone, sv.name, p.name, c.starts_at
  from claimed c
  join salons s on s.id = c.salon_id
  join auth.users u on u.id = s.owner_id
  join services sv on sv.id = c.service_id
  join professionals p on p.id = c.professional_id;
$$;

revoke execute on function claim_client_change_notification(uuid) from public, anon, authenticated;
grant execute on function claim_client_change_notification(uuid) to service_role;

-- ======================================================================
-- 0015_subscription.sql
-- ======================================================================
-- Free trial and subscription status per salon, ready for the payment gateway.
-- The app reads these; only the service role (the future payment webhook) or an
-- admin in the SQL editor can change them, never the salon from the app.

create type subscription_status as enum ('experimental', 'ativa', 'em_atraso', 'cancelada');

alter table salons add column subscription subscription_status not null default 'experimental';
alter table salons add column trial_ends_at timestamptz not null default (now() + interval '30 days');
alter table salons add column paid_until timestamptz;
-- Salons that already exist get 30 days from their creation, and at least 30 days from today.
update salons set trial_ends_at = greatest(created_at + interval '30 days', now() + interval '30 days');

-- Blocks changes to the billing columns from the app's roles. Security definer
-- functions, the service role and the SQL editor run as other roles and pass.
create function protect_billing() returns trigger
language plpgsql as $$
begin
  if current_user in ('anon', 'authenticated') and (
    new.subscription is distinct from old.subscription
    or new.trial_ends_at is distinct from old.trial_ends_at
    or new.paid_until is distinct from old.paid_until
  ) then
    raise exception 'campos_de_faturacao';
  end if;
  return new;
end;
$$;

create trigger salons_protect_billing before update on salons
  for each row execute function protect_billing();

-- A new salon can't start with a longer trial or a paid plan either.
create function new_salon_billing() returns trigger
language plpgsql as $$
begin
  if current_user in ('anon', 'authenticated') then
    new.subscription := 'experimental';
    new.trial_ends_at := now() + interval '30 days';
    new.paid_until := null;
  end if;
  return new;
end;
$$;

create trigger salons_new_billing before insert on salons
  for each row execute function new_salon_billing();

-- ======================================================================
-- 0016_salon_profile.sql
-- ======================================================================
-- Salon profile shown on the booking page and the poster.
-- "if not exists": the live project already got these columns by hand on 2026-11-20.
alter table salons add column if not exists address text;
alter table salons add column if not exists news text;
alter table salons add column if not exists google_review_url text;

-- ======================================================================
-- 0017_admin_invoices.sql
-- ======================================================================
-- CorteCerto's own admin area: the people who run CorteCerto (not salons) set each
-- salon's subscription and upload its monthly invoice; the salon owner downloads it.

create table platform_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table platform_admins enable row level security;
-- Nobody manages admins from the app: add them in the SQL editor.
create policy platform_admins_self on platform_admins for select using (user_id = auth.uid());

create function is_platform_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from platform_admins where user_id = auth.uid())
$$;

create table invoices (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  number text not null check (length(trim(number)) > 0),
  issued_on date not null default current_date,
  period text,
  amount_cents integer not null check (amount_cents >= 0),
  file_path text not null unique,
  created_at timestamptz not null default now()
);
create index invoices_salon on invoices (salon_id, issued_on desc);
alter table invoices enable row level security;
create policy invoices_admin on invoices for all using (is_platform_admin()) with check (is_platform_admin());
create policy invoices_owner_read on invoices for select
  using (exists (select 1 from salons s where s.id = invoices.salon_id and s.owner_id = auth.uid()));

-- The admin sets a salon's plan. Runs as the function owner, so the billing guard
-- (0015) lets it through; the check below keeps it admin-only.
create function admin_set_subscription(
  p_salon uuid, p_status subscription_status, p_paid_until timestamptz, p_trial_ends_at timestamptz
) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_platform_admin() then raise exception 'sem_permissao'; end if;
  update salons set subscription = p_status, paid_until = p_paid_until,
    trial_ends_at = coalesce(p_trial_ends_at, trial_ends_at)
  where id = p_salon;
  if not found then raise exception 'salao_nao_encontrado'; end if;
end;
$$;
revoke execute on function admin_set_subscription(uuid, subscription_status, timestamptz, timestamptz) from anon;

-- Invoice PDFs live in a private storage bucket, one folder per salon: <salon_id>/<file>.pdf.
-- Skipped where there is no Supabase Storage (the plain Postgres used in CI).
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    insert into storage.buckets (id, name, public) values ('invoices', 'invoices', false) on conflict (id) do nothing;
    execute $p$create policy invoices_files_admin on storage.objects for all
      using (bucket_id = 'invoices' and public.is_platform_admin())
      with check (bucket_id = 'invoices' and public.is_platform_admin())$p$;
    execute $p$create policy invoices_files_owner_read on storage.objects for select
      using (bucket_id = 'invoices' and exists (
        select 1 from public.salons s where s.id::text = (storage.foldername(name))[1] and s.owner_id = auth.uid()))$p$;
  end if;
end $$;

-- ======================================================================
-- 0018_team_clients_club_ai.sql
-- ======================================================================
-- 0018: access levels for the team, commissions, the salon's own client list and
-- invitations, a different time suggested by the salon, the Club (monthly
-- membership) and the log behind the AI features.
-- Run once, after 0017. Everything is additive: existing team members keep the
-- access they had ("Receção").

-- ============================================================================
-- 1. Access levels
-- ============================================================================
-- agenda:  agenda, week, bookings, queue and reminders
-- rececao: + clients (list, notes, register, invitations) and the Club members
-- gestor:  + statistics, hours and time off, prices per professional, team and
--            commissions, Club settings
-- dono:    everything, including access, settings, billing, exports and deleting client data
alter table salon_members add column access text not null default 'rececao'
  check (access in ('agenda', 'rececao', 'gestor'));
alter table salon_invites add column access text not null default 'rececao'
  check (access in ('agenda', 'rececao', 'gestor'));

create function access_rank(a text) returns int
language sql immutable as $$
  select case a when 'agenda' then 1 when 'rececao' then 2 when 'gestor' then 3 when 'dono' then 4 else 0 end;
$$;

-- True for the owner, and for team members with at least the given level.
create function has_access(s uuid, need text) returns boolean
language sql stable security definer set search_path = public as $$
  select is_owner(s) or exists (
    select 1 from salon_members m
    where m.salon_id = s and m.user_id = auth.uid() and access_rank(m.access) >= access_rank(need)
  );
$$;
grant execute on function has_access(uuid, text) to authenticated;

-- Client notes are client data: from "Receção" up (the agenda level sees names and phones on bookings only).
drop policy notes_team_read on client_notes;
drop policy notes_team_insert on client_notes;
drop policy notes_team_update on client_notes;
create policy notes_team_read on client_notes for select using (has_access(salon_id, 'rececao'));
create policy notes_team_insert on client_notes for insert with check (has_access(salon_id, 'rececao'));
create policy notes_team_update on client_notes for update using (has_access(salon_id, 'rececao')) with check (has_access(salon_id, 'rececao'));

-- Managers run the team, hours, time off and prices per professional (added next to the owner's policies).
create policy prof_manager_write on professionals for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy pro_hours_manager_write on professional_hours for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy time_off_manager on time_off for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy overrides_manager_write on service_overrides for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

-- Invites carry the level; the owner can change a member's level later (members_owner policy).
create or replace function accept_invites() returns int
language plpgsql security definer set search_path = public as $$
declare
  v_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  r record;
  v_count int := 0;
begin
  if auth.uid() is null or v_email = '' then return 0; end if;
  if exists (select 1 from salons where owner_id = auth.uid()) or exists (select 1 from salon_members where user_id = auth.uid()) then
    return 0;
  end if;
  for r in select * from salon_invites
           where lower(email) = v_email and accepted_at is null and created_at > now() - interval '14 days'
           order by created_at desc limit 1
  loop
    insert into salon_members (salon_id, user_id, email, professional_id, access)
    values (r.salon_id, auth.uid(), v_email, r.professional_id, r.access) on conflict do nothing;
    update salon_invites set accepted_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- role is now 'dono' or the member's level.
create or replace function my_salon() returns table (salon_id uuid, role text, professional_id uuid)
language sql stable security definer set search_path = public as $$
  select id, 'dono', null::uuid from salons where owner_id = auth.uid()
  union all
  select m.salon_id, m.access, m.professional_id from salon_members m where m.user_id = auth.uid()
  limit 1;
$$;

-- ============================================================================
-- 2. Commissions, per professional. Kept apart from `professionals`, which the
--    booking page reads publicly.
-- ============================================================================
create table professional_pay (
  professional_id uuid primary key references professionals(id) on delete cascade,
  salon_id uuid not null references salons(id) on delete cascade,
  -- nenhuma: no commission; percentagem: % of each completed visit; montante: fixed amount per completed visit
  commission_type text not null default 'nenhuma' check (commission_type in ('nenhuma', 'percentagem', 'montante')),
  commission_percent numeric(5,2) check (commission_percent is null or commission_percent between 0 and 100),
  commission_cents int check (commission_cents is null or commission_cents >= 0),
  updated_at timestamptz not null default now(),
  check (commission_type <> 'percentagem' or commission_percent is not null),
  check (commission_type <> 'montante' or commission_cents is not null)
);
alter table professional_pay enable row level security;
create policy pay_manager on professional_pay for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

-- ============================================================================
-- 3. The salon's own client list ("registered" clients) and invitations.
--    Clients are keyed by phone digits, like client_notes and the client list.
-- ============================================================================
create table salon_clients (
  salon_id uuid not null references salons(id) on delete cascade,
  phone_key text not null check (phone_key ~ '^[0-9]{6,15}$'),
  name text not null check (length(trim(name)) between 1 and 120),
  phone text not null,
  email text check (email is null or email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  source text not null default 'salao' check (source in ('salao', 'convite', 'marcacao', 'contactos')),
  invited_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (salon_id, phone_key)
);
alter table salon_clients enable row level security;
create policy clients_owner on salon_clients for all using (is_owner(salon_id)) with check (is_owner(salon_id));
create policy clients_team_read on salon_clients for select using (has_access(salon_id, 'rececao'));
create policy clients_team_insert on salon_clients for insert with check (has_access(salon_id, 'rececao'));
create policy clients_team_update on salon_clients for update using (has_access(salon_id, 'rececao')) with check (has_access(salon_id, 'rececao'));
-- Agenda-level staff only need to know whether a booking's client is already on the list, not who is on it.
create function known_clients(p_salon uuid, p_keys text[]) returns setof text
language sql stable security definer set search_path = public as $$
  select phone_key from salon_clients
  where salon_id = p_salon and phone_key = any(p_keys) and has_access(p_salon, 'agenda');
$$;
grant execute on function known_clients(uuid, text[]) to authenticated;

-- ============================================================================
-- 4. The salon suggests a different time; the client accepts or declines on
--    their private booking page (/m/<id>).
-- ============================================================================
alter table bookings add column proposed_starts_at timestamptz;
alter table bookings add column proposed_at timestamptz;
alter table bookings add column proposal_note text check (proposal_note is null or length(proposal_note) <= 300);
alter table bookings drop constraint if exists bookings_client_action_check;
alter table bookings add constraint bookings_client_action_check
  check (client_action in ('cancelou', 'mudou', 'aceitou', 'recusou'));

-- True when another live booking or a suggested time of this professional overlaps.
create function slot_taken(p_professional uuid, p_from timestamptz, p_to timestamptz, p_except uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from bookings b
    where b.professional_id = p_professional and b.id is distinct from p_except
      and b.status in ('pendente', 'confirmada', 'concluida')
      and (
        (b.starts_at < p_to and b.ends_at > p_from)
        or (b.proposed_starts_at is not null
            and b.proposed_starts_at < p_to
            and b.proposed_starts_at + (b.ends_at - b.starts_at) > p_from)
      )
  ) or is_time_off(p_professional, p_from, p_to);
$$;
revoke execute on function slot_taken(uuid, timestamptz, timestamptz, uuid) from public, anon, authenticated;

create function propose_booking_time(p_booking uuid, p_starts_at timestamptz, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare b bookings;
begin
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'marcacao_inexistente'; end if;
  if not has_access(b.salon_id, 'agenda') then raise exception 'sem_permissao'; end if;
  if b.status not in ('pendente', 'confirmada') then raise exception 'marcacao_fechada'; end if;
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  if slot_taken(b.professional_id, p_starts_at, p_starts_at + (b.ends_at - b.starts_at), b.id) then
    raise exception 'horario_ocupado';
  end if;
  update bookings set proposed_starts_at = p_starts_at, proposed_at = now(),
         proposal_note = nullif(trim(coalesce(p_note, '')), ''), client_action = null, client_action_at = null
  where id = p_booking;
end;
$$;
grant execute on function propose_booking_time(uuid, timestamptz, text) to authenticated;

create function withdraw_booking_proposal(p_booking uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_salon uuid;
begin
  select salon_id into v_salon from bookings where id = p_booking;
  if v_salon is null or not has_access(v_salon, 'agenda') then raise exception 'sem_permissao'; end if;
  update bookings set proposed_starts_at = null, proposed_at = null, proposal_note = null where id = p_booking;
end;
$$;
grant execute on function withdraw_booking_proposal(uuid) to authenticated;

-- The client's answer. Accepting moves the booking to the suggested time and confirms it
-- (it stays pending while a deposit is still owed).
create function respond_to_proposal(p_booking uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
declare
  b bookings;
  v_length interval;
begin
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'marcacao_inexistente'; end if;
  if b.proposed_starts_at is null then raise exception 'sem_proposta'; end if;
  if b.status not in ('pendente', 'confirmada') then raise exception 'marcacao_fechada'; end if;
  if not p_accept then
    update bookings set proposed_starts_at = null, proposed_at = null, client_action = 'recusou', client_action_at = now()
    where id = p_booking;
    return;
  end if;
  if b.proposed_starts_at < now() then raise exception 'horario_passado'; end if;
  v_length := b.ends_at - b.starts_at;
  if is_time_off(b.professional_id, b.proposed_starts_at, b.proposed_starts_at + v_length) then
    raise exception 'horario_ocupado';
  end if;
  update bookings set starts_at = b.proposed_starts_at, ends_at = b.proposed_starts_at + v_length,
         status = case when b.deposit = 'pendente' then 'pendente'::booking_status else 'confirmada'::booking_status end,
         proposed_starts_at = null, proposed_at = null, proposal_note = null,
         client_action = 'aceitou', client_action_at = now(), reminder_sent_at = null
  where id = p_booking;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;
grant execute on function respond_to_proposal(uuid, boolean) to anon, authenticated;

-- Busy time for the booking pages now includes times the salon has suggested and is holding.
create or replace function busy_slots(p_salon uuid, p_from timestamptz, p_to timestamptz)
returns table (professional_id uuid, starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = public as $$
  select b.professional_id, b.starts_at, b.ends_at
  from bookings b
  where b.salon_id = p_salon
    and b.status in ('pendente', 'confirmada', 'concluida')
    and b.starts_at < p_to and b.ends_at > p_from
  union all
  select b.professional_id, b.proposed_starts_at, b.proposed_starts_at + (b.ends_at - b.starts_at)
  from bookings b
  where b.salon_id = p_salon and b.proposed_starts_at is not null
    and b.status in ('pendente', 'confirmada')
    and b.proposed_starts_at < p_to and b.proposed_starts_at + (b.ends_at - b.starts_at) > p_from
  union all
  select p.id, t.starts_at, t.ends_at
  from time_off t
  join professionals p on p.salon_id = t.salon_id and (t.professional_id is null or t.professional_id = p.id)
  where t.salon_id = p_salon and t.starts_at < p_to and t.ends_at > p_from;
$$;

-- The client's page also shows a suggested time. The returned columns change, so drop and create.
drop function booking_for_client(uuid);
create function booking_for_client(p_booking uuid)
returns table (
  id uuid, status booking_status, deposit deposit_status, starts_at timestamptz, ends_at timestamptz,
  client_name text, salon_id uuid, salon_slug text, salon_name text, salon_theme text,
  salon_timezone text, salon_whatsapp text, mbway_number text, deposit_cents int,
  client_change_hours smallint, service_id uuid, service_name text, duration_min int,
  price_cents int, professional_id uuid, professional_name text,
  proposed_starts_at timestamptz, proposal_note text
)
language sql stable security definer set search_path = public as $$
  select b.id, b.status, b.deposit, b.starts_at, b.ends_at, b.client_name,
         s.id, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.mbway_number, s.deposit_cents,
         s.client_change_hours, sv.id, sv.name,
         (extract(epoch from (b.ends_at - b.starts_at)) / 60)::int,
         coalesce(b.price_cents, sv.price_cents), p.id, p.name,
         b.proposed_starts_at, b.proposal_note
  from bookings b
  join salons s on s.id = b.salon_id
  join services sv on sv.id = b.service_id
  join professionals p on p.id = b.professional_id
  where b.id = p_booking;
$$;
grant execute on function booking_for_client(uuid) to anon, authenticated;

-- ============================================================================
-- 5. The Club: a monthly membership the salon sells. Payment goes straight to
--    the salon (MB Way or at the counter); the app keeps who is a member.
-- ============================================================================
create table salon_club (
  salon_id uuid primary key references salons(id) on delete cascade,
  active boolean not null default false,
  name text not null default 'Clube' check (length(trim(name)) between 1 and 60),
  price_cents int not null default 0 check (price_cents >= 0),
  benefits text not null default '' check (length(benefits) <= 500),
  no_deposit boolean not null default true, -- members book without a deposit
  updated_at timestamptz not null default now()
);
alter table salon_club enable row level security;
create policy club_public_read on salon_club for select using (true);
create policy club_manager_write on salon_club for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

create table club_members (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  phone_key text not null check (phone_key ~ '^[0-9]{6,15}$'),
  name text not null,
  phone text not null,
  -- pedido: asked to join online, waiting for the first payment; ativo; cancelado
  status text not null default 'pedido' check (status in ('pedido', 'ativo', 'cancelado')),
  pay_method text not null default 'mbway' check (pay_method in ('mbway', 'balcao')),
  price_cents int not null default 0 check (price_cents >= 0), -- price when joined
  started_at timestamptz,
  paid_until date,
  cancelled_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index club_members_open on club_members (salon_id, phone_key) where status in ('pedido', 'ativo');
alter table club_members enable row level security;
create policy club_members_owner on club_members for all using (is_owner(salon_id)) with check (is_owner(salon_id));
create policy club_members_team_read on club_members for select using (has_access(salon_id, 'rececao'));
create policy club_members_team_insert on club_members for insert with check (has_access(salon_id, 'rececao'));
create policy club_members_team_update on club_members for update using (has_access(salon_id, 'rececao')) with check (has_access(salon_id, 'rececao'));

-- A client asks to join from the booking page. The salon activates it once paid.
create function join_club(p_salon uuid, p_name text, p_phone text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  c salon_club;
  v_key text := phone_key(p_phone);
  v_id uuid;
begin
  select * into c from salon_club where salon_id = p_salon and active;
  if not found then raise exception 'clube_fechado'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 or length(v_key) < 9 then raise exception 'dados_cliente'; end if;
  select id into v_id from club_members where salon_id = p_salon and phone_key = v_key and status in ('pedido', 'ativo');
  if v_id is not null then return v_id; end if;
  insert into club_members (salon_id, phone_key, name, phone, price_cents)
  values (p_salon, v_key, trim(p_name), trim(p_phone), c.price_cents)
  returning id into v_id;
  return v_id;
end;
$$;
grant execute on function join_club(uuid, text, text) to anon, authenticated;

-- Members with a paid month book without a deposit (when the salon chose that benefit).
create or replace function create_booking(
  p_salon uuid, p_service uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price int;
  v_deposit int;
  v_member boolean;
  v_id uuid;
begin
  perform 1 from services where id = p_service and salon_id = p_salon and active;
  if not found then raise exception 'servico_invalido'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon and active;
  if not found then raise exception 'profissional_invalido'; end if;
  select e.price_cents, e.duration_min into v_price, v_duration from effective_service(p_service, p_professional) e;
  if v_duration is null then raise exception 'servico_invalido'; end if;
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  if length(trim(p_client_name)) = 0 or length(trim(p_client_phone)) < 9 then
    raise exception 'dados_cliente';
  end if;
  -- Time off, and times the salon has suggested to another client, are taken.
  if slot_taken(p_professional, p_starts_at, p_starts_at + make_interval(mins => v_duration), null) then
    raise exception 'horario_ocupado';
  end if;
  select deposit_cents into v_deposit from salons where id = p_salon;
  select exists (
    select 1 from club_members m join salon_club c on c.salon_id = m.salon_id
    where m.salon_id = p_salon and m.phone_key = phone_key(p_client_phone) and m.status = 'ativo'
      and c.active and c.no_deposit and (m.paid_until is null or m.paid_until >= current_date)
  ) into v_member;

  insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at,
                        client_name, client_phone, consent_messages, deposit, price_cents)
  values (p_salon, p_service, p_professional, p_starts_at,
          p_starts_at + make_interval(mins => v_duration),
          trim(p_client_name), trim(p_client_phone), coalesce(p_consent, false),
          case when v_deposit > 0 and not v_member then 'pendente'::deposit_status else 'nenhum' end, v_price)
  returning id into v_id;
  return v_id;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;

-- Forgetting a client (RGPD) also removes them from the list and the Club.
create or replace function forget_client_rows(p_salon uuid, p_key text) returns int
language plpgsql security definer set search_path = public as $$
declare v_count int;
begin
  update bookings set status = 'cancelada'
  where salon_id = p_salon and phone_key(client_phone) = p_key
    and status in ('pendente', 'confirmada') and starts_at > now();
  update bookings set client_name = 'Cliente apagado', client_phone = '', consent_messages = false
  where salon_id = p_salon and phone_key(client_phone) = p_key;
  get diagnostics v_count = row_count;
  delete from client_notes where salon_id = p_salon and phone_key = p_key;
  delete from walkins where salon_id = p_salon and phone_key(client_phone) = p_key;
  delete from salon_clients where salon_id = p_salon and phone_key = p_key;
  update club_members set name = 'Cliente apagado', phone = '', status = 'cancelado', cancelled_at = coalesce(cancelled_at, now())
  where salon_id = p_salon and phone_key = p_key;
  return v_count;
end;
$$;

-- ============================================================================
-- 6. AI features: one log row per request, for usage limits per plan and for
--    support. Requests go through the Worker (/api/ai/<feature>); no photo or
--    model output is kept here, only what was asked and whether it worked.
-- ============================================================================
create table ai_requests (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid references salons(id) on delete cascade,
  feature text not null check (feature ~ '^[a-z-]{3,40}$'),
  status text not null check (status in ('feito', 'erro', 'indisponivel', 'limite')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index ai_requests_salon_month on ai_requests (salon_id, created_at);
alter table ai_requests enable row level security;
-- Written only by the Worker (service role); the salon can read its own usage.
create policy ai_requests_read on ai_requests for select using (has_access(salon_id, 'gestor'));

-- ======================================================================
-- 0019_free_slots_branding.sql
-- ======================================================================
-- 0019: filling a freed slot, and the salon's own brand (logo, cover, text, gallery).
-- Run once, after 0018.

-- The salon's brand (section 2 below); added first because the offer page shows the logo.
alter table salons add column logo_path text;
alter table salons add column cover_path text;
alter table salons add column about text check (about is null or length(about) <= 600);

-- Managers change the brand; the rest of the salon row stays with the owner.
create function set_salon_brand(p_salon uuid, p_logo text, p_cover text, p_about text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not has_access(p_salon, 'gestor') then raise exception 'sem_permissao'; end if;
  if (p_logo is not null and p_logo !~ ('^' || p_salon::text || '/')) or (p_cover is not null and p_cover !~ ('^' || p_salon::text || '/')) then
    raise exception 'ficheiro_invalido';
  end if;
  update salons set logo_path = p_logo, cover_path = p_cover, about = nullif(trim(coalesce(p_about, '')), '') where id = p_salon;
end;
$$;
grant execute on function set_salon_brand(uuid, text, text, text) to authenticated;

-- ============================================================================
-- 1. Filling a freed slot
-- ============================================================================
-- When a booking is cancelled or a client doesn't show, the salon opens an offer
-- for that time and sends its link to several clients by WhatsApp. The first to
-- accept gets it: someone already booked later moves to it, or someone new books it.

-- Clients can ask, on their booking page, to be told when an earlier time opens.
alter table bookings add column wants_earlier boolean not null default false;

create function set_wants_earlier(p_booking uuid, p_on boolean) returns void
language sql security definer set search_path = public as $$
  update bookings set wants_earlier = coalesce(p_on, false)
  where id = p_booking and status in ('pendente', 'confirmada');
$$;
grant execute on function set_wants_earlier(uuid, boolean) to anon, authenticated;

-- The client's page shows the "earlier time" choice and the salon's logo.
drop function booking_for_client(uuid);
create function booking_for_client(p_booking uuid)
returns table (
  id uuid, status booking_status, deposit deposit_status, starts_at timestamptz, ends_at timestamptz,
  client_name text, salon_id uuid, salon_slug text, salon_name text, salon_theme text,
  salon_timezone text, salon_whatsapp text, mbway_number text, deposit_cents int,
  client_change_hours smallint, service_id uuid, service_name text, duration_min int,
  price_cents int, professional_id uuid, professional_name text,
  proposed_starts_at timestamptz, proposal_note text, wants_earlier boolean, salon_logo text
)
language sql stable security definer set search_path = public as $$
  select b.id, b.status, b.deposit, b.starts_at, b.ends_at, b.client_name,
         s.id, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.mbway_number, s.deposit_cents,
         s.client_change_hours, sv.id, sv.name,
         (extract(epoch from (b.ends_at - b.starts_at)) / 60)::int,
         coalesce(b.price_cents, sv.price_cents), p.id, p.name,
         b.proposed_starts_at, b.proposal_note, b.wants_earlier, s.logo_path
  from bookings b
  join salons s on s.id = b.salon_id
  join services sv on sv.id = b.service_id
  join professionals p on p.id = b.professional_id
  where b.id = p_booking;
$$;
grant execute on function booking_for_client(uuid) to anon, authenticated;

create table slot_offers (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  professional_id uuid not null references professionals(id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  filled_booking uuid references bookings(id) on delete set null,
  filled_at timestamptz,
  closed_at timestamptz -- the salon withdrew it
);
create index slot_offers_salon on slot_offers (salon_id, starts_at);
alter table slot_offers enable row level security;
create policy slot_offers_team on slot_offers for select using (has_access(salon_id, 'agenda'));
create policy slot_offers_team_close on slot_offers for update using (has_access(salon_id, 'agenda')) with check (has_access(salon_id, 'agenda'));

-- Opens an offer for a free time of one professional (from the agenda).
create function offer_free_slot(p_salon uuid, p_professional uuid, p_starts_at timestamptz, p_ends_at timestamptz) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not has_access(p_salon, 'agenda') then raise exception 'sem_permissao'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon;
  if not found then raise exception 'profissional_invalido'; end if;
  if p_ends_at <= greatest(p_starts_at, now()) then raise exception 'horario_passado'; end if;
  if slot_taken(p_professional, p_starts_at, p_ends_at, null) then raise exception 'horario_ocupado'; end if;
  -- One open offer per time: reuse it.
  select id into v_id from slot_offers
  where professional_id = p_professional and starts_at = p_starts_at and ends_at = p_ends_at
    and filled_booking is null and closed_at is null;
  if v_id is not null then return v_id; end if;
  insert into slot_offers (salon_id, professional_id, starts_at, ends_at, created_by)
  values (p_salon, p_professional, p_starts_at, p_ends_at, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;
grant execute on function offer_free_slot(uuid, uuid, timestamptz, timestamptz) to authenticated;

-- What a client sees on the offer's page. state: aberta, ocupada (taken), expirada.
create function slot_offer_for_client(p_offer uuid)
returns table (
  id uuid, state text, starts_at timestamptz, ends_at timestamptz,
  salon_id uuid, salon_slug text, salon_name text, salon_theme text, salon_timezone text, salon_whatsapp text,
  salon_logo text, professional_id uuid, professional_name text
)
language sql stable security definer set search_path = public as $$
  select o.id,
         case when o.filled_booking is not null then 'ocupada'
              when o.closed_at is not null or o.starts_at < now() - interval '5 minutes' then 'expirada'
              else 'aberta' end,
         o.starts_at, o.ends_at, s.id, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.logo_path,
         p.id, p.name
  from slot_offers o
  join salons s on s.id = o.salon_id
  join professionals p on p.id = o.professional_id
  where o.id = p_offer;
$$;
grant execute on function slot_offer_for_client(uuid) to anon, authenticated;

-- Locks an open offer, or explains why it can't be taken.
create function lock_open_offer(p_offer uuid) returns slot_offers
language plpgsql security definer set search_path = public as $$
declare o slot_offers;
begin
  select * into o from slot_offers where id = p_offer for update;
  if not found then raise exception 'oferta_inexistente'; end if;
  if o.filled_booking is not null then raise exception 'vaga_ocupada'; end if;
  if o.closed_at is not null or o.starts_at < now() - interval '5 minutes' then raise exception 'vaga_expirada'; end if;
  return o;
end;
$$;
revoke execute on function lock_open_offer(uuid) from public, anon, authenticated;

-- A client already booked later with the same professional moves to the freed time.
create function take_slot_offer_move(p_offer uuid, p_booking uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  o slot_offers;
  b bookings;
  v_start timestamptz;
begin
  o := lock_open_offer(p_offer);
  select * into b from bookings where id = p_booking for update;
  if not found or b.salon_id <> o.salon_id or b.professional_id <> o.professional_id then raise exception 'marcacao_inexistente'; end if;
  if b.status not in ('pendente', 'confirmada') then raise exception 'marcacao_fechada'; end if;
  if b.starts_at <= o.starts_at then raise exception 'ja_mais_cedo'; end if;
  -- Starts when the offer starts, or now if it already began (a no-show noticed late).
  v_start := greatest(o.starts_at, date_trunc('minute', now()));
  if v_start + (b.ends_at - b.starts_at) > o.ends_at then raise exception 'nao_cabe'; end if;
  update bookings set starts_at = v_start, ends_at = v_start + (b.ends_at - b.starts_at),
         client_action = 'mudou', client_action_at = now(), reminder_sent_at = null,
         proposed_starts_at = null, proposed_at = null, proposal_note = null, wants_earlier = false
  where id = p_booking;
  update slot_offers set filled_booking = p_booking, filled_at = now() where id = p_offer;
exception when exclusion_violation then
  raise exception 'vaga_ocupada';
end;
$$;
grant execute on function take_slot_offer_move(uuid, uuid) to anon, authenticated;

-- Someone new books the freed time, choosing a service that fits in it.
create function take_slot_offer_new(p_offer uuid, p_service uuid, p_name text, p_phone text, p_consent boolean) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  o slot_offers;
  v_duration int;
  v_start timestamptz;
  v_id uuid;
begin
  o := lock_open_offer(p_offer);
  select e.duration_min into v_duration from effective_service(p_service, o.professional_id) e;
  if v_duration is null then raise exception 'servico_invalido'; end if;
  v_start := greatest(o.starts_at, date_trunc('minute', now()));
  if v_start + make_interval(mins => v_duration) > o.ends_at then raise exception 'nao_cabe'; end if;
  v_id := create_booking(o.salon_id, p_service, o.professional_id, v_start, p_name, p_phone, p_consent);
  update slot_offers set filled_booking = v_id, filled_at = now() where id = p_offer;
  return v_id;
end;
$$;
grant execute on function take_slot_offer_new(uuid, uuid, text, text, boolean) to anon, authenticated;

-- ============================================================================
-- 2. The salon's brand: logo, cover photo, a short text, and a gallery of work.
--    Files live in the public bucket "salon-media", one folder per salon.
-- ============================================================================

create table salon_photos (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  path text not null,
  caption text check (caption is null or length(caption) <= 120),
  position int not null default 0,
  created_at timestamptz not null default now()
);
create index salon_photos_salon on salon_photos (salon_id, position);
alter table salon_photos enable row level security;
create policy photos_public_read on salon_photos for select using (true);
create policy photos_manager_write on salon_photos for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
-- At most 24 photos per salon (storage stays small on the free plan).
create function salon_photos_limit() returns trigger language plpgsql as $$
begin
  if (select count(*) from salon_photos where salon_id = new.salon_id) >= 24 then raise exception 'limite_fotos'; end if;
  return new;
end;
$$;
create trigger salon_photos_limit before insert on salon_photos for each row execute function salon_photos_limit();

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('salon-media', 'salon-media', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
    on conflict (id) do nothing;
    execute $p$create policy salon_media_read on storage.objects for select using (bucket_id = 'salon-media')$p$;
    execute $p$create policy salon_media_write on storage.objects for insert
      with check (bucket_id = 'salon-media' and public.has_access(((storage.foldername(name))[1])::uuid, 'gestor'))$p$;
    execute $p$create policy salon_media_update on storage.objects for update
      using (bucket_id = 'salon-media' and public.has_access(((storage.foldername(name))[1])::uuid, 'gestor'))$p$;
    execute $p$create policy salon_media_delete on storage.objects for delete
      using (bucket_id = 'salon-media' and public.has_access(((storage.foldername(name))[1])::uuid, 'gestor'))$p$;
  end if;
end $$;

-- ======================================================================
-- 0020_promotions.sql
-- ======================================================================
-- 0020: promotions tied to the agenda. A promotion has its own booking link
-- (/s/<salon>?promo=<code>), days, hours, services and dates; bookings made through it
-- get the discount and are counted, so the salon sees what each promotion brought in.
-- Run once, after 0019.

create table promotions (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  code text not null check (code ~ '^[a-z0-9-]{3,40}$'),
  title text not null check (length(trim(title)) between 1 and 80),
  message text not null default '' check (length(message) <= 1200), -- the post's caption
  -- percentagem: % off; montante: € off; oferta: price unchanged, plus a gift (e.g. "barba grátis")
  kind text not null check (kind in ('percentagem', 'montante', 'oferta')),
  percent int check (percent is null or percent between 1 and 90),
  amount_cents int check (amount_cents is null or amount_cents > 0),
  gift text check (gift is null or length(gift) <= 80),
  service_ids uuid[],                 -- null: every service
  weekdays smallint[],                -- 0 = Sunday … 6 = Saturday; null: every day
  time_from time, time_to time,       -- in the salon's time zone; null: all day
  starts_on date not null default current_date,
  ends_on date,
  active boolean not null default true,
  image_path text,                    -- the salon's own picture for the post (bucket salon-media)
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check (kind <> 'percentagem' or percent is not null),
  check (kind <> 'montante' or amount_cents is not null),
  check (kind <> 'oferta' or gift is not null),
  check (ends_on is null or ends_on >= starts_on),
  check ((time_from is null) = (time_to is null) and (time_from is null or time_to > time_from)),
  unique (salon_id, code)
);
alter table promotions enable row level security;
-- A promotion is public by nature (it is posted); clients' booking page reads it.
create policy promos_public_read on promotions for select using (true);
create policy promos_manager_write on promotions for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

alter table bookings add column promotion_id uuid references promotions(id) on delete set null;
alter table bookings add column price_before_cents int; -- the price before the promotion

-- Whether a promotion covers this service at this time.
create function promo_applies(p promotions, p_service uuid, p_starts_at timestamptz) returns boolean
language sql stable set search_path = public as $$
  select p.active
     and (p.service_ids is null or p_service = any(p.service_ids))
     and (p_starts_at at time zone s.timezone)::date >= p.starts_on
     and (p.ends_on is null or (p_starts_at at time zone s.timezone)::date <= p.ends_on)
     and (p.weekdays is null or extract(dow from p_starts_at at time zone s.timezone)::smallint = any(p.weekdays))
     and (p.time_from is null or ((p_starts_at at time zone s.timezone)::time >= p.time_from
                                  and (p_starts_at at time zone s.timezone)::time < p.time_to))
  from salons s where s.id = p.salon_id;
$$;

-- Price after the promotion.
create function promo_price(p promotions, p_price int) returns int
language sql immutable as $$
  select case p.kind
    when 'percentagem' then round(p_price * (100 - p.percent) / 100.0)::int
    when 'montante' then greatest(0, p_price - p.amount_cents)
    else p_price end;
$$;

-- Booking through a promotion's link: books as usual, then applies the promotion when it
-- covers that service and time (otherwise the booking stands at the normal price).
create function create_booking_with_promo(
  p_salon uuid, p_service uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean, p_promo uuid
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  p promotions;
  b bookings;
begin
  v_id := create_booking(p_salon, p_service, p_professional, p_starts_at, p_client_name, p_client_phone, p_consent);
  select * into p from promotions where id = p_promo and salon_id = p_salon;
  if found and promo_applies(p, p_service, p_starts_at) then
    select * into b from bookings where id = v_id;
    update bookings set promotion_id = p.id, price_before_cents = b.price_cents, price_cents = promo_price(p, b.price_cents)
    where id = v_id;
  end if;
  return v_id;
end;
$$;
grant execute on function create_booking_with_promo(uuid, uuid, uuid, timestamptz, text, text, boolean, uuid) to anon, authenticated;

-- ======================================================================
-- 0021_function_search_path.sql
-- ======================================================================
-- 0021: pin search_path on three helper functions from 0018–0020 (Supabase security advisor).
-- Already applied to the live project on 2026-11-22.
alter function access_rank(text) set search_path = public;
alter function salon_photos_limit() set search_path = public;
alter function promo_price(promotions, int) set search_path = public;

-- ======================================================================
-- 0022_business_home_packages.sql
-- ======================================================================
-- 0022: business profile, home visits, and packages (combos, event quotes, prepaid packs).
-- Run once, after 0021.

-- ============================================================================
-- 1. Business profile: the areas the salon covers, how clients come, where it works
-- ============================================================================
alter type salon_type add value if not exists 'estetica';
alter type salon_type add value if not exists 'sobrancelhas';
alter type salon_type add value if not exists 'maquilhagem';
alter type salon_type add value if not exists 'massagem';

alter table salons add column areas text[] not null default '{}'
  check (areas <@ array['barbearia', 'cabeleireiro', 'unhas', 'depilacao', 'estetica', 'sobrancelhas', 'maquilhagem', 'massagem']);
-- marcacao: appointments only; sem_marcacao: walk-ins only; ambos
alter table salons add column booking_mode text not null default 'ambos' check (booking_mode in ('marcacao', 'sem_marcacao', 'ambos'));
-- salao: in the salon; domicilio: only at clients' homes (no salon); ambos
alter table salons add column work_place text not null default 'salao' check (work_place in ('salao', 'domicilio', 'ambos'));

-- ============================================================================
-- 2. Home visits. Price = services + the zone's travel fee + the fees the owner
--    switched on (early, evening, weekend, always). Travel time blocks the
--    professional's agenda before and after the visit.
-- ============================================================================
create table home_settings (
  salon_id uuid primary key references salons(id) on delete cascade,
  active boolean not null default false,
  min_order_cents int not null default 0 check (min_order_cents >= 0),
  deposit_required boolean not null default true, -- the salon's deposit applies to every home visit
  updated_at timestamptz not null default now()
);
create table home_zones (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  name text not null check (length(trim(name)) between 1 and 60),
  postcodes text[] not null default '{}', -- 4-digit prefixes, e.g. {2900, 2910}; empty: chosen by name
  fee_cents int not null default 0 check (fee_cents >= 0),
  travel_min int not null default 15 check (travel_min between 0 and 180), -- each way
  position int not null default 0,
  active boolean not null default true
);
create table home_fees (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  label text not null check (length(trim(label)) between 1 and 60),
  -- sempre: every home visit; antes_das: starts before `at`; depois_das: starts at or after `at`; fim_de_semana: Saturday or Sunday
  rule text not null check (rule in ('sempre', 'antes_das', 'depois_das', 'fim_de_semana')),
  at time,
  amount_cents int not null check (amount_cents > 0),
  active boolean not null default true,
  check (rule not in ('antes_das', 'depois_das') or at is not null)
);
alter table services add column at_home boolean not null default false;
alter table professionals add column at_home boolean not null default false;
-- Managers choose which services go out (professionals they already manage, 0018).
create policy svc_manager_update on services for update using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

alter table home_settings enable row level security;
alter table home_zones enable row level security;
alter table home_fees enable row level security;
create policy home_settings_read on home_settings for select using (true);
create policy home_zones_read on home_zones for select using (true);
create policy home_fees_read on home_fees for select using (true);
create policy home_settings_write on home_settings for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy home_zones_write on home_zones for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy home_fees_write on home_fees for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));

alter table bookings add column location text not null default 'salao' check (location in ('salao', 'domicilio'));
alter table bookings add column travel_min int not null default 0 check (travel_min >= 0);
alter table bookings add column home_fee_cents int not null default 0 check (home_fee_cents >= 0);
alter table bookings add column en_route_at timestamptz;
alter table bookings add column started_at timestamptz;
alter table bookings add column finished_at timestamptz;

-- The address is kept apart: only the owner, the front desk and the professional who goes can read it.
create table booking_addresses (
  booking_id uuid primary key references bookings(id) on delete cascade,
  salon_id uuid not null references salons(id) on delete cascade,
  professional_id uuid not null,
  address text not null check (length(trim(address)) between 3 and 200),
  postcode text check (postcode is null or postcode ~ '^[0-9]{4}(-[0-9]{3})?$'),
  notes text check (notes is null or length(notes) <= 300),
  zone_name text
);
alter table booking_addresses enable row level security;
create function is_my_professional(s uuid, p uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from salon_members m where m.salon_id = s and m.user_id = auth.uid() and m.professional_id = p);
$$;
create policy addresses_read on booking_addresses for select using (has_access(salon_id, 'rececao') or is_my_professional(salon_id, professional_id));
create policy addresses_owner on booking_addresses for all using (is_owner(salon_id)) with check (is_owner(salon_id));

-- Taken now also counts the travel time around home visits.
create or replace function slot_taken(p_professional uuid, p_from timestamptz, p_to timestamptz, p_except uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from bookings b
    where b.professional_id = p_professional and b.id is distinct from p_except
      and b.status in ('pendente', 'confirmada', 'concluida')
      and (
        (b.starts_at - make_interval(mins => b.travel_min) < p_to and b.ends_at + make_interval(mins => b.travel_min) > p_from)
        or (b.proposed_starts_at is not null
            and b.proposed_starts_at < p_to
            and b.proposed_starts_at + (b.ends_at - b.starts_at) > p_from)
      )
  ) or is_time_off(p_professional, p_from, p_to);
$$;

create or replace function busy_slots(p_salon uuid, p_from timestamptz, p_to timestamptz)
returns table (professional_id uuid, starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = public as $$
  select b.professional_id, b.starts_at - make_interval(mins => b.travel_min), b.ends_at + make_interval(mins => b.travel_min)
  from bookings b
  where b.salon_id = p_salon
    and b.status in ('pendente', 'confirmada', 'concluida')
    and b.starts_at - make_interval(mins => b.travel_min) < p_to and b.ends_at + make_interval(mins => b.travel_min) > p_from
  union all
  select b.professional_id, b.proposed_starts_at, b.proposed_starts_at + (b.ends_at - b.starts_at)
  from bookings b
  where b.salon_id = p_salon and b.proposed_starts_at is not null
    and b.status in ('pendente', 'confirmada')
    and b.proposed_starts_at < p_to and b.proposed_starts_at + (b.ends_at - b.starts_at) > p_from
  union all
  select p.id, t.starts_at, t.ends_at
  from time_off t
  join professionals p on p.salon_id = t.salon_id and (t.professional_id is null or t.professional_id = p.id)
  where t.salon_id = p_salon and t.starts_at < p_to and t.ends_at > p_from;
$$;

-- The home fees for a visit starting at p_starts_at (salon time).
create function home_fees_for(p_salon uuid, p_starts_at timestamptz) returns int
language sql stable security definer set search_path = public as $$
  select coalesce(sum(f.amount_cents), 0)::int
  from home_fees f join salons s on s.id = f.salon_id
  where f.salon_id = p_salon and f.active and (
    f.rule = 'sempre'
    or (f.rule = 'antes_das' and (p_starts_at at time zone s.timezone)::time < f.at)
    or (f.rule = 'depois_das' and (p_starts_at at time zone s.timezone)::time >= f.at)
    or (f.rule = 'fim_de_semana' and extract(dow from p_starts_at at time zone s.timezone) in (0, 6))
  );
$$;

-- Books a home visit: the service and professional must go out, the zone sets the fee and travel time.
create function create_home_booking(
  p_salon uuid, p_service uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean,
  p_zone uuid, p_address text, p_postcode text, p_notes text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  h home_settings;
  z home_zones;
  v_duration int;
  v_price int;
  v_id uuid;
begin
  select * into h from home_settings where salon_id = p_salon and active;
  if not found then raise exception 'domicilio_fechado'; end if;
  select * into z from home_zones where id = p_zone and salon_id = p_salon and active;
  if not found then raise exception 'zona_invalida'; end if;
  perform 1 from services where id = p_service and salon_id = p_salon and active and at_home;
  if not found then raise exception 'servico_invalido'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon and active and at_home;
  if not found then raise exception 'profissional_invalido'; end if;
  if length(trim(coalesce(p_address, ''))) < 3 then raise exception 'morada_invalida'; end if;
  select e.price_cents, e.duration_min into v_price, v_duration from effective_service(p_service, p_professional) e;
  if v_price < h.min_order_cents then raise exception 'pedido_minimo'; end if;
  -- Travel there and back must be free too.
  if slot_taken(p_professional, p_starts_at - make_interval(mins => z.travel_min),
                p_starts_at + make_interval(mins => v_duration + z.travel_min), null) then
    raise exception 'horario_ocupado';
  end if;
  v_id := create_booking(p_salon, p_service, p_professional, p_starts_at, p_client_name, p_client_phone, p_consent);
  update bookings set location = 'domicilio', travel_min = z.travel_min,
         home_fee_cents = z.fee_cents + home_fees_for(p_salon, p_starts_at),
         deposit = case when h.deposit_required and (select deposit_cents from salons where id = p_salon) > 0 then 'pendente'::deposit_status else deposit end
  where id = v_id;
  insert into booking_addresses (booking_id, salon_id, professional_id, address, postcode, notes, zone_name)
  values (v_id, p_salon, p_professional, trim(p_address), nullif(trim(coalesce(p_postcode, '')), ''), nullif(trim(coalesce(p_notes, '')), ''), z.name);
  return v_id;
end;
$$;
grant execute on function create_home_booking(uuid, uuid, uuid, timestamptz, text, text, boolean, uuid, text, text, text) to anon, authenticated;

-- ============================================================================
-- 3. Packages. One model, three ways to sell:
--    combo:  several services in one visit, a fixed price, optional extras
--    evento: weddings and other events, by request and proposal (trial + the day, per person)
--    pack:   prepaid sessions of one service, used over time
-- ============================================================================
create table packages (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  mode text not null check (mode in ('combo', 'evento', 'pack')),
  name text not null check (length(trim(name)) between 1 and 80),
  description text not null default '' check (length(description) <= 800),
  price_cents int not null check (price_cents >= 0),     -- combo: the price; evento: the main person; pack: the whole pack
  per_guest_cents int check (per_guest_cents is null or per_guest_cents >= 0), -- evento: each extra person
  max_guests int check (max_guests is null or max_guests between 0 and 30),
  includes_trial boolean not null default false,          -- evento: a trial session weeks before
  extra_hour_cents int check (extra_hour_cents is null or extra_hour_cents >= 0), -- evento: each hour of waiting on the day
  deposit_pct int check (deposit_pct is null or deposit_pct between 0 and 100),   -- evento
  sessions int check (sessions is null or sessions between 2 and 50),             -- pack
  valid_days int check (valid_days is null or valid_days between 7 and 730),      -- pack
  active boolean not null default true,
  position int not null default 0,
  image_path text,
  created_at timestamptz not null default now(),
  check (mode <> 'pack' or sessions is not null)
);
create table package_items (
  id uuid primary key default gen_random_uuid(),
  package_id uuid not null references packages(id) on delete cascade,
  service_id uuid not null references services(id) on delete cascade,
  optional boolean not null default false,  -- an extra the client may add
  extra_price_cents int check (extra_price_cents is null or extra_price_cents >= 0), -- price as an extra; null: the service's price
  position int not null default 0
);
create index package_items_package on package_items (package_id, position);
alter table salon_photos add column package_id uuid references packages(id) on delete set null;

alter table packages enable row level security;
alter table package_items enable row level security;
create policy packages_read on packages for select using (true);
create policy packages_write on packages for all using (has_access(salon_id, 'gestor')) with check (has_access(salon_id, 'gestor'));
create policy package_items_read on package_items for select using (true);
create policy package_items_write on package_items for all
  using (has_access((select salon_id from packages p where p.id = package_id), 'gestor'))
  with check (has_access((select salon_id from packages p where p.id = package_id), 'gestor'));

alter table bookings add column package_id uuid references packages(id) on delete set null;
alter table bookings add column package_summary text; -- what the visit includes, as booked
alter table bookings add column waiting_min int not null default 0 check (waiting_min >= 0); -- evento: paid waiting time

-- Combo: one visit with the package's services and the extras chosen, by one professional.
create function create_package_booking(
  p_salon uuid, p_package uuid, p_professional uuid, p_starts_at timestamptz,
  p_client_name text, p_client_phone text, p_consent boolean, p_extras uuid[]
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  k packages;
  v_duration int := 0;
  v_price int;
  v_first uuid;
  v_names text;
  v_deposit int;
  v_id uuid;
begin
  select * into k from packages where id = p_package and salon_id = p_salon and active and mode = 'combo';
  if not found then raise exception 'pacote_invalido'; end if;
  perform 1 from professionals where id = p_professional and salon_id = p_salon and active;
  if not found then raise exception 'profissional_invalido'; end if;
  if p_starts_at < now() then raise exception 'horario_passado'; end if;
  if length(trim(coalesce(p_client_name, ''))) = 0 or length(trim(coalesce(p_client_phone, ''))) < 9 then raise exception 'dados_cliente'; end if;
  select coalesce(sum(e.duration_min), 0),
         k.price_cents + coalesce(sum(case when i.optional then coalesce(i.extra_price_cents, e.price_cents) else 0 end), 0),
         (array_agg(i.service_id order by i.optional, i.position))[1],
         string_agg(s.name, ' + ' order by i.optional, i.position)
    into v_duration, v_price, v_first, v_names
  from package_items i
  join services s on s.id = i.service_id and s.active
  cross join lateral effective_service(i.service_id, p_professional) e
  where i.package_id = p_package and (not i.optional or i.id = any(coalesce(p_extras, '{}')));
  if v_first is null or v_duration = 0 then raise exception 'pacote_invalido'; end if;
  if slot_taken(p_professional, p_starts_at, p_starts_at + make_interval(mins => v_duration), null) then raise exception 'horario_ocupado'; end if;
  select deposit_cents into v_deposit from salons where id = p_salon;
  insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at, client_name, client_phone,
                        consent_messages, deposit, price_cents, package_id, package_summary)
  values (p_salon, v_first, p_professional, p_starts_at, p_starts_at + make_interval(mins => v_duration),
          trim(p_client_name), trim(p_client_phone), coalesce(p_consent, false),
          case when v_deposit > 0 then 'pendente'::deposit_status else 'nenhum' end, v_price, k.id, k.name || ': ' || v_names)
  returning id into v_id;
  return v_id;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;
grant execute on function create_package_booking(uuid, uuid, uuid, timestamptz, text, text, boolean, uuid[]) to anon, authenticated;

-- Evento: the client asks, the salon proposes, the client accepts.
create table package_requests (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  package_id uuid not null references packages(id) on delete cascade,
  client_name text not null,
  client_phone text not null,
  consent_messages boolean not null default false,
  event_date date not null,
  event_time time,
  place text not null default 'salao' check (place in ('salao', 'local')),
  address text check (address is null or length(address) <= 200),
  guests int not null default 0 check (guests between 0 and 30),
  extras uuid[] not null default '{}',
  message text check (message is null or length(message) <= 600),
  estimate_cents int not null default 0,
  -- pedido: sent by the client; proposta: the salon answered; aceite; recusado (by the client); cancelado (by the salon)
  status text not null default 'pedido' check (status in ('pedido', 'proposta', 'aceite', 'recusado', 'cancelado')),
  proposal_cents int,
  deposit_cents int,
  proposal_note text check (proposal_note is null or length(proposal_note) <= 600),
  professional_id uuid references professionals(id) on delete set null,
  trial_at timestamptz,
  trial_min int,
  event_at timestamptz,
  event_min int,
  valid_until date,
  created_at timestamptz not null default now(),
  answered_at timestamptz,
  decided_at timestamptz
);
create index package_requests_salon on package_requests (salon_id, created_at desc);
alter table package_requests enable row level security;
create policy package_requests_team on package_requests for select using (has_access(salon_id, 'rececao'));
create policy package_requests_team_update on package_requests for update using (has_access(salon_id, 'rececao')) with check (has_access(salon_id, 'rececao'));
alter table bookings add column package_request_id uuid references package_requests(id) on delete set null;

create function request_package(
  p_package uuid, p_name text, p_phone text, p_consent boolean, p_date date, p_time time,
  p_place text, p_address text, p_guests int, p_extras uuid[], p_message text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  k packages;
  v_extras int;
  v_id uuid;
begin
  select * into k from packages where id = p_package and active and mode = 'evento';
  if not found then raise exception 'pacote_invalido'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 or length(phone_key(p_phone)) < 9 then raise exception 'dados_cliente'; end if;
  if p_date is null or p_date < current_date then raise exception 'data_invalida'; end if;
  if coalesce(p_guests, 0) < 0 or (k.max_guests is not null and p_guests > k.max_guests) then raise exception 'convidados_invalidos'; end if;
  select coalesce(sum(coalesce(i.extra_price_cents, s.price_cents)), 0) into v_extras
  from package_items i join services s on s.id = i.service_id
  where i.package_id = p_package and i.optional and i.id = any(coalesce(p_extras, '{}'));
  insert into package_requests (salon_id, package_id, client_name, client_phone, consent_messages, event_date, event_time,
                                place, address, guests, extras, message, estimate_cents)
  values (k.salon_id, k.id, trim(p_name), trim(p_phone), coalesce(p_consent, false), p_date, p_time,
          case when p_place = 'local' then 'local' else 'salao' end, nullif(trim(coalesce(p_address, '')), ''),
          coalesce(p_guests, 0), coalesce(p_extras, '{}'), nullif(trim(coalesce(p_message, '')), ''),
          k.price_cents + coalesce(k.per_guest_cents, 0) * coalesce(p_guests, 0) + v_extras)
  returning id into v_id;
  return v_id;
end;
$$;
grant execute on function request_package(uuid, text, text, boolean, date, time, text, text, int, uuid[], text) to anon, authenticated;

-- What the client sees on /pedido/<id>.
create function package_request_for_client(p_request uuid)
returns table (
  id uuid, status text, package_name text, package_description text, includes_trial boolean, extra_hour_cents int,
  event_date date, event_time time, place text, guests int, estimate_cents int,
  proposal_cents int, deposit_cents int, proposal_note text, trial_at timestamptz, event_at timestamptz, valid_until date,
  client_name text, salon_slug text, salon_name text, salon_theme text, salon_timezone text, salon_whatsapp text,
  mbway_number text, salon_logo text, professional_name text
)
language sql stable security definer set search_path = public as $$
  select r.id, r.status, k.name, k.description, k.includes_trial, k.extra_hour_cents,
         r.event_date, r.event_time, r.place, r.guests, r.estimate_cents,
         r.proposal_cents, r.deposit_cents, r.proposal_note, r.trial_at, r.event_at, r.valid_until,
         r.client_name, s.slug, s.name, s.theme, s.timezone, s.whatsapp, s.mbway_number, s.logo_path, p.name
  from package_requests r
  join packages k on k.id = r.package_id
  join salons s on s.id = r.salon_id
  left join professionals p on p.id = r.professional_id
  where r.id = p_request;
$$;
grant execute on function package_request_for_client(uuid) to anon, authenticated;

-- The salon sends its proposal: price, deposit, the trial and the day in the agenda's terms.
create function propose_package(
  p_request uuid, p_price int, p_deposit int, p_note text, p_professional uuid,
  p_trial_at timestamptz, p_trial_min int, p_event_at timestamptz, p_event_min int, p_valid_until date
) returns void
language plpgsql security definer set search_path = public as $$
declare r package_requests;
begin
  select * into r from package_requests where id = p_request for update;
  if not found then raise exception 'pedido_inexistente'; end if;
  if not has_access(r.salon_id, 'rececao') then raise exception 'sem_permissao'; end if;
  if r.status not in ('pedido', 'proposta') then raise exception 'pedido_fechado'; end if;
  if p_price is null or p_price < 0 or coalesce(p_deposit, 0) < 0 or coalesce(p_deposit, 0) > p_price then raise exception 'valores_invalidos'; end if;
  perform 1 from professionals where id = p_professional and salon_id = r.salon_id;
  if not found then raise exception 'profissional_invalido'; end if;
  if p_event_at is null or coalesce(p_event_min, 0) < 15 or (p_trial_at is not null and coalesce(p_trial_min, 0) < 15) then raise exception 'datas_invalidas'; end if;
  update package_requests set status = 'proposta', proposal_cents = p_price, deposit_cents = coalesce(p_deposit, 0),
         proposal_note = nullif(trim(coalesce(p_note, '')), ''), professional_id = p_professional,
         trial_at = p_trial_at, trial_min = p_trial_min, event_at = p_event_at, event_min = p_event_min,
         valid_until = p_valid_until, answered_at = now()
  where id = p_request;
end;
$$;
grant execute on function propose_package(uuid, int, int, text, uuid, timestamptz, int, timestamptz, int, date) to authenticated;

-- The client accepts: the trial and the day go into the agenda as bookings.
create function accept_package_proposal(p_request uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  r package_requests;
  k packages;
  v_service uuid;
begin
  select * into r from package_requests where id = p_request for update;
  if not found then raise exception 'pedido_inexistente'; end if;
  if r.status <> 'proposta' then raise exception 'sem_proposta'; end if;
  if r.valid_until is not null and r.valid_until < current_date then raise exception 'proposta_expirada'; end if;
  select * into k from packages where id = r.package_id;
  select service_id into v_service from package_items where package_id = k.id and not optional order by position limit 1;
  if v_service is null then select service_id into v_service from package_items where package_id = k.id order by position limit 1; end if;
  if v_service is null then raise exception 'pacote_invalido'; end if;
  if r.trial_at is not null then
    if slot_taken(r.professional_id, r.trial_at, r.trial_at + make_interval(mins => r.trial_min), null) then raise exception 'horario_ocupado'; end if;
    insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at, client_name, client_phone, consent_messages,
                          deposit, price_cents, package_id, package_summary, package_request_id, location)
    values (r.salon_id, v_service, r.professional_id, r.trial_at, r.trial_at + make_interval(mins => r.trial_min),
            r.client_name, r.client_phone, r.consent_messages, 'nenhum', 0, k.id, k.name || ': prova', r.id, 'salao');
  end if;
  if slot_taken(r.professional_id, r.event_at, r.event_at + make_interval(mins => r.event_min), null) then raise exception 'horario_ocupado'; end if;
  insert into bookings (salon_id, service_id, professional_id, starts_at, ends_at, client_name, client_phone, consent_messages,
                        deposit, price_cents, package_id, package_summary, package_request_id, location)
  values (r.salon_id, v_service, r.professional_id, r.event_at, r.event_at + make_interval(mins => r.event_min),
          r.client_name, r.client_phone, r.consent_messages,
          case when coalesce(r.deposit_cents, 0) > 0 then 'pendente'::deposit_status else 'nenhum' end,
          r.proposal_cents, k.id, k.name || case when r.guests > 0 then ' (+' || r.guests || ')' else '' end, r.id,
          case when r.place = 'local' then 'domicilio' else 'salao' end);
  update package_requests set status = 'aceite', decided_at = now() where id = p_request;
exception when exclusion_violation then
  raise exception 'horario_ocupado';
end;
$$;
grant execute on function accept_package_proposal(uuid) to anon, authenticated;

create function decline_package_proposal(p_request uuid) returns void
language sql security definer set search_path = public as $$
  update package_requests set status = 'recusado', decided_at = now() where id = p_request and status in ('pedido', 'proposta');
$$;
grant execute on function decline_package_proposal(uuid) to anon, authenticated;

-- Pack: prepaid sessions. The client asks to buy; the salon activates once paid and marks each session used.
create table client_packs (
  id uuid primary key default gen_random_uuid(),
  salon_id uuid not null references salons(id) on delete cascade,
  package_id uuid not null references packages(id) on delete cascade,
  phone_key text not null check (phone_key ~ '^[0-9]{6,15}$'),
  client_name text not null,
  client_phone text not null,
  sessions_total int not null check (sessions_total > 0),
  sessions_used int not null default 0 check (sessions_used >= 0),
  price_cents int not null check (price_cents >= 0),
  status text not null default 'pedido' check (status in ('pedido', 'ativo', 'terminado', 'cancelado')),
  paid_at timestamptz,
  expires_on date,
  created_at timestamptz not null default now(),
  check (sessions_used <= sessions_total)
);
create index client_packs_salon on client_packs (salon_id, phone_key);
alter table client_packs enable row level security;
create policy client_packs_team on client_packs for select using (has_access(salon_id, 'agenda'));
create policy client_packs_team_write on client_packs for insert with check (has_access(salon_id, 'rececao'));
create policy client_packs_team_update on client_packs for update using (has_access(salon_id, 'agenda')) with check (has_access(salon_id, 'agenda'));
alter table bookings add column client_pack_id uuid references client_packs(id) on delete set null;

create function buy_pack(p_package uuid, p_name text, p_phone text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  k packages;
  v_id uuid;
begin
  select * into k from packages where id = p_package and active and mode = 'pack';
  if not found then raise exception 'pacote_invalido'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 or length(phone_key(p_phone)) < 9 then raise exception 'dados_cliente'; end if;
  insert into client_packs (salon_id, package_id, phone_key, client_name, client_phone, sessions_total, price_cents)
  values (k.salon_id, k.id, phone_key(p_phone), trim(p_name), trim(p_phone), k.sessions, k.price_cents)
  returning id into v_id;
  return v_id;
end;
$$;
grant execute on function buy_pack(uuid, text, text) to anon, authenticated;

-- Marks one session of an active pack as used by a booking; the visit itself is then free (paid with the pack).
create function use_pack_session(p_pack uuid, p_booking uuid) returns int
language plpgsql security definer set search_path = public as $$
declare
  c client_packs;
  b bookings;
begin
  select * into c from client_packs where id = p_pack for update;
  if not found or not has_access(c.salon_id, 'agenda') then raise exception 'sem_permissao'; end if;
  if c.status <> 'ativo' then raise exception 'pack_inativo'; end if;
  if c.expires_on is not null and c.expires_on < current_date then raise exception 'pack_expirado'; end if;
  select * into b from bookings where id = p_booking and salon_id = c.salon_id;
  if not found then raise exception 'marcacao_inexistente'; end if;
  if b.client_pack_id is not null then raise exception 'ja_usado'; end if;
  update bookings set client_pack_id = c.id, price_cents = 0 where id = p_booking;
  update client_packs set sessions_used = sessions_used + 1,
         status = case when sessions_used + 1 >= sessions_total then 'terminado' else status end
  where id = p_pack;
  return c.sessions_total - c.sessions_used - 1;
end;
$$;
grant execute on function use_pack_session(uuid, uuid) to authenticated;

-- Forgetting a client also removes their packs and event requests.
create or replace function forget_client_rows(p_salon uuid, p_key text) returns int
language plpgsql security definer set search_path = public as $$
declare v_count int;
begin
  update bookings set status = 'cancelada'
  where salon_id = p_salon and phone_key(client_phone) = p_key
    and status in ('pendente', 'confirmada') and starts_at > now();
  update bookings set client_name = 'Cliente apagado', client_phone = '', consent_messages = false
  where salon_id = p_salon and phone_key(client_phone) = p_key;
  get diagnostics v_count = row_count;
  delete from booking_addresses a using bookings b where a.booking_id = b.id and b.salon_id = p_salon and b.client_phone = '' and b.client_name = 'Cliente apagado';
  delete from client_notes where salon_id = p_salon and phone_key = p_key;
  delete from walkins where salon_id = p_salon and phone_key(client_phone) = p_key;
  delete from salon_clients where salon_id = p_salon and phone_key = p_key;
  update club_members set name = 'Cliente apagado', phone = '', status = 'cancelado', cancelled_at = coalesce(cancelled_at, now())
  where salon_id = p_salon and phone_key = p_key;
  update client_packs set client_name = 'Cliente apagado', client_phone = '', status = 'cancelado' where salon_id = p_salon and phone_key = p_key;
  delete from package_requests where salon_id = p_salon and phone_key(client_phone) = p_key;
  return v_count;
end;
$$;

-- ======================================================================
-- 0023_billing_lock.sql
-- ======================================================================
-- 0023: gentle lock for salons that don't pay.
-- 14 days after the trial ends (or after the paid period ends) with no payment,
-- the salon's account becomes read-only: the owner and the team can still see
-- everything, but can't change it, and new online bookings are paused.
-- Bookings already made stay as they are, and clients can still cancel them.
-- Access comes back as soon as the admin marks the salon paid in /admin
-- (admin_set_subscription: "Ativa" with a future "Pago até").
-- A cancelled salon locks when its paid period ends, without the 14 days.

create function salon_locked(p_salon uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when s.subscription = 'cancelada' then now() > coalesce(s.paid_until, s.trial_ends_at)
      when s.subscription = 'experimental' then now() > s.trial_ends_at + interval '14 days'
      when s.subscription = 'ativa' then s.paid_until is not null and now() > s.paid_until + interval '14 days'
      when s.subscription = 'em_atraso' then now() > coalesce(s.paid_until, s.trial_ends_at) + interval '14 days'
      else false
    end
    from salons s where s.id = p_salon
  ), false)
$$;
grant execute on function salon_locked(uuid) to anon, authenticated;

-- Who is asking: the role the API request runs as. It stays the same inside
-- security definer functions, so it covers the owner's RPCs too. Scheduled
-- jobs and the service role are never blocked.
create function locked_write_refused(p_salon uuid, p_op text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare v_role text := coalesce(current_setting('role', true), 'none');
begin
  if v_role not in ('anon', 'authenticated') then return false; end if;
  if current_setting('cortecerto.allow_locked', true) = 'on' then return false; end if;
  if is_platform_admin() then return false; end if;
  if not salon_locked(p_salon) then return false; end if;
  -- New rows (a booking, a place in the queue…) are paused for everyone.
  -- Changes and deletes only for the salon's team: a client can still cancel.
  return p_op = 'INSERT' or v_role = 'authenticated';
end;
$$;
revoke execute on function locked_write_refused(uuid, text) from public, anon, authenticated;

create function refuse_when_locked() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_salon uuid;
begin
  v_salon := case when tg_op = 'DELETE' then old.salon_id else new.salon_id end;
  if locked_write_refused(v_salon, tg_op) then raise exception 'salao_bloqueado'; end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

-- Every table the salon writes to, except: legal acceptances (accepting the
-- terms must still work), invoices (admin only), AI and error logs, and the
-- team tables (accepting an invite runs at sign-in).
do $$
declare t text;
begin
  foreach t in array array[
    'bookings', 'booking_addresses', 'client_notes', 'client_packs', 'club_members',
    'home_fees', 'home_settings', 'home_zones', 'opening_hours', 'package_requests',
    'packages', 'professional_hours', 'professional_pay', 'professionals', 'promotions',
    'salon_clients', 'salon_club', 'salon_photos', 'service_overrides', 'services',
    'slot_offers', 'time_off', 'walkins'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('create trigger %I before insert or update or delete on %I for each row execute function refuse_when_locked()', t || '_locked', t);
    end if;
  end loop;
end $$;

-- The salon's own settings. The admin's plan change still goes through.
create function refuse_salon_when_locked() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if locked_write_refused(old.id, tg_op) then raise exception 'salao_bloqueado'; end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;
create trigger salons_locked before update on salons
  for each row execute function refuse_salon_when_locked();

-- A client's right to be forgotten still works while the salon is locked.
create or replace function forget_client(p_salon uuid, p_key text) returns int
language plpgsql security definer set search_path = public as $$
declare v int;
begin
  if not is_owner(p_salon) then raise exception 'sem_permissao'; end if;
  if p_key !~ '^[0-9]{6,15}$' then raise exception 'telefone_invalido'; end if;
  perform set_config('cortecerto.allow_locked', 'on', true);
  v := forget_client_rows(p_salon, p_key);
  perform set_config('cortecerto.allow_locked', '', true);
  return v;
end;
$$;

-- ======================================================================
-- 0024_admin_dashboard.sql
-- ======================================================================
-- 0024: data for the admin dashboard (/admin).
-- 1. bookings.source: where a booking came from. The live project already had this
--    column from an early setup script that never became a migration; this makes
--    every database the same, and adds 'salao' for bookings the team makes in the panel.
-- 2. admin_dashboard(): one call that returns everything the dashboard shows, for
--    platform admins only. It reads tables the admin can't read directly (bookings,
--    owners' last login, errors, scheduled jobs), and returns counts, never clients' details.

alter table bookings add column if not exists source text not null default 'online';
do $$
declare c record;
begin
  for c in select conname from pg_constraint
           where conrelid = 'public.bookings'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%source%'
  loop
    execute format('alter table bookings drop constraint %I', c.conname);
  end loop;
end $$;
alter table bookings add constraint bookings_source_check
  check (source in ('online', 'salao', 'telefone', 'presencial'));

-- A booking made by someone signed in to the salon's team (the panel, "next visit")
-- is the salon's; a client on the public booking page is never signed in.
create function set_booking_source() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.source = 'online' and auth.uid() is not null and has_access(new.salon_id, 'agenda') then
    new.source := 'salao';
  end if;
  return new;
end $$;
create trigger bookings_source before insert on bookings
  for each row execute function set_booking_source();

create function admin_dashboard() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_salons jsonb; v_weeks jsonb; v_ai jsonb; v_errors jsonb; v_jobs jsonb := '[]'::jsonb;
begin
  if not is_platform_admin() then raise exception 'sem_permissao'; end if;

  select coalesce(jsonb_agg(row_to_json(x) order by x.created_at desc), '[]') into v_salons from (
    select s.id, s.name, s.slug, s.type, s.created_at, s.subscription, s.trial_ends_at, s.paid_until,
           s.address, s.whatsapp, (s.logo_path is not null) as has_logo,
           u.email as owner_email, u.last_sign_in_at,
           (select count(*) from services v where v.salon_id = s.id and v.active) as services,
           (select count(*) from professionals p where p.salon_id = s.id and p.active) as professionals,
           (select count(distinct weekday) from opening_hours h where h.salon_id = s.id) as open_days,
           (select count(*) from salon_members m where m.salon_id = s.id) as team,
           (select count(*) from salon_clients c where c.salon_id = s.id) as clients,
           b.total as bookings, b.last30 as bookings_30d, b.online30 as online_30d, b.noshow30 as noshow_30d,
           b.value30 as value_30d_cents, b.first_at as first_booking_at, b.first_online_at, b.last_at as last_booking_at,
           (select count(*) from walkins w where w.salon_id = s.id and w.created_at > now() - interval '30 days') as walkins_30d,
           (select count(*) from promotions pr where pr.salon_id = s.id) as promotions,
           (select count(*) from client_packs cp where cp.salon_id = s.id) as packs,
           (select count(*) from ai_requests a where a.salon_id = s.id and a.status = 'feito' and a.created_at > now() - interval '30 days') as ai_30d
    from salons s
    left join auth.users u on u.id = s.owner_id
    left join lateral (
      select count(*) filter (where bk.status <> 'cancelada') as total,
             count(*) filter (where bk.created_at > now() - interval '30 days' and bk.status <> 'cancelada') as last30,
             count(*) filter (where bk.created_at > now() - interval '30 days' and bk.status <> 'cancelada' and bk.source = 'online') as online30,
             count(*) filter (where bk.starts_at > now() - interval '30 days' and bk.status = 'faltou') as noshow30,
             coalesce(sum(coalesce(bk.price_cents, sv.price_cents)) filter (
               where bk.starts_at > now() - interval '30 days' and bk.starts_at <= now() and bk.status in ('confirmada', 'concluida')), 0) as value30,
             min(bk.created_at) as first_at,
             min(bk.created_at) filter (where bk.source = 'online') as first_online_at,
             max(bk.created_at) as last_at
      from bookings bk left join services sv on sv.id = bk.service_id
      where bk.salon_id = s.id
    ) b on true
  ) x;

  -- Bookings made per week, last 12 weeks (Monday start, Lisbon time).
  select coalesce(jsonb_agg(row_to_json(w) order by w.week), '[]') into v_weeks from (
    select to_char(g.week, 'YYYY-MM-DD') as week,
           count(bk.id) filter (where bk.source = 'online') as online,
           count(bk.id) filter (where bk.source <> 'online') as salao,
           coalesce(sum(coalesce(bk.price_cents, sv.price_cents)), 0) as value_cents
    from generate_series(date_trunc('week', (now() at time zone 'Europe/Lisbon')) - interval '11 weeks',
                         date_trunc('week', (now() at time zone 'Europe/Lisbon')), interval '1 week') as g(week)
    left join bookings bk on bk.status <> 'cancelada'
      and date_trunc('week', bk.created_at at time zone 'Europe/Lisbon') = g.week
    left join services sv on sv.id = bk.service_id
    group by g.week
  ) w;

  -- AI this month by feature and result.
  select coalesce(jsonb_agg(row_to_json(a)), '[]') into v_ai from (
    select feature, status, count(*) as n, count(distinct salon_id) as salons
    from ai_requests where created_at >= date_trunc('month', now())
    group by feature, status order by feature, status
  ) a;

  -- Browser errors of the last 7 days, grouped by message.
  select coalesce(jsonb_agg(row_to_json(e)), '[]') into v_errors from (
    select message, count(*) as n, max(at) as last_at, (array_agg(path order by at desc))[1] as path
    from client_errors where at > now() - interval '7 days'
    group by message order by max(at) desc limit 20
  ) e;

  -- Scheduled jobs (pg_cron), when the extension is installed.
  if to_regclass('cron.job_run_details') is not null then
    execute $q$
      select coalesce(jsonb_agg(row_to_json(j)), '[]') from (
        select jb.jobname, jb.schedule, jb.active,
               (select d.status from cron.job_run_details d where d.jobid = jb.jobid order by d.start_time desc limit 1) as last_status,
               (select d.start_time from cron.job_run_details d where d.jobid = jb.jobid order by d.start_time desc limit 1) as last_run,
               (select count(*) from cron.job_run_details d where d.jobid = jb.jobid and d.status = 'failed' and d.start_time > now() - interval '7 days') as failed_7d
        from cron.job jb order by jb.jobname
      ) j $q$ into v_jobs;
  end if;

  return jsonb_build_object('generated_at', now(), 'salons', v_salons, 'weeks', v_weeks, 'ai', v_ai, 'errors', v_errors, 'jobs', v_jobs);
end $$;
revoke execute on function admin_dashboard() from public, anon;
grant execute on function admin_dashboard() to authenticated;

commit;
